-- Lesson content rewrite: c_ap2_d1, c_ap2_d2, c_ap2_d3, c_ap2_d4
-- New slide format (terms at a glance, examples, comparisons, diagrams,
-- practice questions). Title slides kept; mini-exam questions untouched.
-- Safe to re-run: the current content is backed up once first.

create table if not exists lesson_content_backup (
  lesson_id uuid not null, content_blocks jsonb not null,
  backed_up_at timestamptz not null default now(), note text);
alter table lesson_content_backup enable row level security;

insert into lesson_content_backup (lesson_id, content_blocks, note)
