-- What the A+ Core 2 Exam Actually Tests
update lessons set content_blocks = '[{"text": "What the A+ Core 2 Exam Actually Tests", "type": "title", "overview": "A map of the four domains covered in this course, and how CompTIA actually scores the current 220-1202 exam.", "examContext": "Why this matters: domain weights tell you where to put your study time before you spend a single hour on content."}, {"type": "paragraph", "text": "Full A+ certification requires passing **both** Core 1 and Core 2. This course covers **Core 2**: operating systems, security, software troubleshooting and operational procedures."}, {"type": "term_set", "heading": "The exam at a glance", "terms": [{"term": "Exam", "short": "CompTIA A+ Core 2, 220-1202, which replaced 220-1102."}, {"term": "Length", "short": "Up to 90 questions in 90 minutes."}, {"term": "Question types", "short": "Multiple choice, drag and drop, performance based."}, {"term": "Passing score", "short": "700 on a 100 to 900 scale."}, {"term": "Version pairing", "short": "Core 1 and Core 2 must come from the same series: 1201 with 1202."}]}, {"type": "compare", "heading": "The four domains and their weight", "columns": ["Weight"], "rows": [{"label": "1. Operating Systems", "values": ["28%"]}, {"label": "2. Security", "values": ["28%"]}, {"label": "3. Software Troubleshooting", "values": ["23%"]}, {"label": "4. Operational Procedures", "values": ["21%"]}]}, {"type": "callout", "variant": "tip", "text": "Operating Systems and Security together are 56% of your score."}]'::jsonb where id = 'e05e8864-836f-47cd-bb29-29f6b6a9e6d8';

-- How to Use Orivian
update lessons set content_blocks = '[{"text": "How to Use Orivian", "type": "title", "overview": "How a domain''s lessons, recap, and checkpoint fit together, and what it takes to mark a lesson complete.", "examContext": "Why this matters: understanding the platform''s rhythm up front means you spend your time studying, not figuring out the interface."}, {"type": "paragraph", "text": "Every domain in this course follows the same pattern. Learn it once and you know it everywhere."}, {"type": "diagram", "heading": "Inside a domain", "diagram": {"kind": "flow", "steps": [{"label": "Lessons", "note": "Each lesson ends in a 10-question mini-exam. 80% to pass; retake as often as you like."}, {"label": "Domain recap", "note": "The highest-yield facts from every lesson, plus rapid practice questions. No exam."}, {"label": "Domain checkpoint", "note": "A longer exam across the whole domain, with fresh scenarios. The real test of whether it stuck."}]}}, {"type": "term_set", "heading": "How a lesson is laid out", "terms": [{"term": "Key terms at a glance", "short": "Every term with a one-line definition, often next to a diagram."}, {"term": "Breakdown", "short": "Terms in depth, each with an \"In practice\" example."}, {"term": "Side by side", "short": "Comparison tables for the pairs the exam loves, with an exam cue row."}, {"term": "How this shows up on the exam", "short": "Practice questions: pick an answer, then see why it''s right and what the trap was. Not scored."}, {"term": "Mini-exam", "short": "The graded questions at the end. You can review every past attempt afterwards."}]}, {"type": "term_set", "heading": "Finding your way", "terms": [{"term": "The trail map", "short": "Each course page shows your path as a trail: covered ground in green, your next waypoint in gold."}, {"term": "Next waypoint", "short": "The card at the top of the course page always points to your next step."}, {"term": "Study timer", "short": "Counts only while a lesson or exam is visible in front of you. For your awareness; never graded."}, {"term": "Listen", "short": "Any slide can be read aloud. Turn on auto-play in Voice settings to hear each slide as you press Next."}, {"term": "Keyboard", "short": "Arrow keys move between slides, L listens, N opens notes."}]}, {"type": "term_set", "heading": "Your notes", "terms": [{"term": "Write a note", "short": "Open Notes in any lesson and type; it''s linked to that lesson automatically."}, {"term": "Save to notes", "short": "Select any sentence in a lesson and tap Save to notes to keep it as a quote."}, {"term": "My Notes", "short": "Everything you''ve saved, on the Notes page, grouped by course and lesson."}], "intro": "Notes are private to you and follow your account to any device."}, {"type": "callout", "variant": "tip", "text": "One or two lessons done attentively beat a skimmed marathon. Use the recap right before the checkpoint."}]'::jsonb where id = 'a25672d1-0bd8-473f-8f68-5f37e61234c7';

-- A Study Strategy That Works
update lessons set content_blocks = '[{"text": "A Study Strategy That Works", "type": "title", "overview": "A short, practical approach to pacing your study time and building the scenario-recognition skill A+ Core 2 actually tests.", "examContext": "Why this matters: Core 2 leans heavily on ''given a scenario'' questions that expect you to pick the right Windows setting, command, or security control, not just recall a definition."}, {"type": "paragraph", "text": "Core 2 describes real support calls: a locked-out user, a suspicious pop-up, a slow laptop. It asks which setting, tool or command you''d use. If you have a Windows machine, practice in Settings, Control Panel and the command line as you go."}, {"type": "term_set", "heading": "How to study", "terms": [{"term": "Repeat OS and Security most", "short": "Editions, settings, commands and hardening, cold."}, {"term": "Don''t skip the smaller domains", "short": "Troubleshooting and Operational Procedures are still 44% together."}, {"term": "Learn the new AI objective", "short": "AI content risks, data privacy and appropriate workplace use are new on 220-1202."}]}, {"type": "scenario", "prompt": "A user''s PC shows signs of malware and is sending strange traffic. What should the technician do **first**?", "choices": [{"id": "a", "text": "Run a full antivirus scan"}, {"id": "b", "text": "Isolate the PC from the network"}, {"id": "c", "text": "Reinstall Windows"}, {"id": "d", "text": "Delete the user''s profile"}], "answer": "b", "why": "Contain before you clean: isolation stops it spreading.", "trap": "Scanning feels like the obvious move, but a connected infected machine can keep spreading while you scan."}, {"type": "callout", "variant": "tip", "text": "For security scenarios, containment comes before cleanup."}]'::jsonb where id = 'd00de1b7-7973-4642-af82-f127492b3b96';

-- Common OS Types and Purposes
update lessons set content_blocks = '[{"text": "Common OS Types and Purposes", "type": "title", "overview": "The major categories of operating system you''ll support (workstation, mobile, server, embedded/IoT), and the filesystems each one commonly uses.", "examContext": "Why this matters: 220-1202 opens Domain 1 by expecting you to match an OS or filesystem to its intended use case and compatibility constraints."}, {"type": "compare", "heading": "Operating system categories", "columns": ["Examples", "Notes"], "rows": [{"label": "Workstation", "values": ["Windows, macOS, Linux, ChromeOS", "Most A+ support work"]}, {"label": "Mobile", "values": ["iOS, iPadOS, Android", "Different update, app and security models"]}, {"label": "Server", "values": ["Windows Server, Linux server distributions", "Built for many users and network services"]}, {"label": "Embedded / IoT", "values": ["Thermostats, printers, POS terminals", "Minimal interface, locked down"]}]}, {"type": "compare", "heading": "Filesystems", "columns": ["Platform", "Notes"], "rows": [{"label": "NTFS", "values": ["Windows", "Permissions, EFS, compression, journaling"]}, {"label": "exFAT", "values": ["Cross-platform", "No journaling; flash media over 32 GB"]}, {"label": "ReFS", "values": ["Windows Server", "Large-scale, fault-tolerant storage"]}, {"label": "APFS", "values": ["macOS, iOS", "Built for SSDs; snapshots, strong encryption"]}, {"label": "ext4", "values": ["Linux", "Standard native filesystem"]}, {"label": "XFS", "values": ["Linux", "High performance, large files"]}], "intro": "220-1202 dropped ext3 and added ReFS and XFS."}, {"type": "key_term", "term": "Journaling filesystem", "definition": "Logs pending changes before committing them, so it recovers cleanly after a crash. NTFS, ReFS, ext4, XFS and APFS journal; FAT32 doesn''t.", "example": "After a power cut, an ext4 server replays its journal in seconds instead of running a long full-disk check."}, {"type": "scenario", "prompt": "A user needs a USB drive that both Windows and macOS can read and write natively, with files larger than 4 GB. Which filesystem?", "choices": [{"id": "a", "text": "NTFS"}, {"id": "b", "text": "FAT32"}, {"id": "c", "text": "exFAT"}, {"id": "d", "text": "APFS"}], "answer": "c", "why": "exFAT is cross-platform without FAT32''s 4 GB file limit.", "trap": "NTFS write support on macOS is limited without extra drivers."}, {"type": "scenario", "prompt": "Which filesystem is built for fault-tolerant, large-scale Windows Server storage?", "choices": [{"id": "a", "text": "exFAT"}, {"id": "b", "text": "ReFS"}, {"id": "c", "text": "ext4"}, {"id": "d", "text": "APFS"}], "answer": "b", "why": "ReFS is the Resilient File System."}, {"type": "callout", "variant": "tip", "text": "Cross-platform USB drive: exFAT. Know ReFS and XFS, which are new on this version."}]'::jsonb where id = 'b22ec324-3e33-48ab-9a9c-e3da43d68785';

-- OS Installations and Upgrades in a Diverse Environment
update lessons set content_blocks = '[{"text": "OS Installations and Upgrades in a Diverse Environment", "type": "title", "overview": "How to plan and execute an OS installation or upgrade, including boot methods, partitioning schemes, and larger-scale deployment strategies.", "examContext": "Why this matters: 220-1202 tests installation/upgrade methods in real deployment contexts, including newer objectives like zero-touch deployment and multiboot setups."}, {"type": "compare", "heading": "Installation types", "columns": ["Keeps", "Use when"], "rows": [{"label": "In-place upgrade", "values": ["Apps, files, settings", "Hardware and current OS support the new version"]}, {"label": "Clean install", "values": ["Nothing", "Corruption, big changes or new hardware"]}, {"label": "Repair / refresh", "values": ["User data, sometimes apps", "Fixing a broken installation"]}, {"label": "Multiboot", "values": ["Each OS on its own partition", "Choosing an OS at startup via a boot manager"]}]}, {"type": "term_set", "heading": "Boot methods", "terms": [{"term": "Internal drive", "short": "The normal installed OS."}, {"term": "USB", "short": "Common installation media."}, {"term": "Optical", "short": "DVD; mostly legacy."}, {"term": "PXE", "short": "Boots an image over the network for mass imaging."}, {"term": "Recovery partition", "short": "Hidden factory reset and repair tools."}]}, {"type": "compare", "heading": "Modern vs. legacy boot", "columns": ["GPT + UEFI", "MBR + BIOS"], "rows": [{"label": "Partitions", "values": ["Many", "4 primary"]}, {"label": "Drive size", "values": ["Beyond 2 TB", "Up to 2 TB"]}, {"label": "Secure Boot", "values": ["Yes", "No"]}], "intro": "**TPM** is a security chip that stores hardware-backed keys, for example for BitLocker."}, {"type": "key_term", "term": "Zero-touch deployment", "definition": "A new device configures and enrolls itself on first boot from a cloud management service, with little or no technician work.", "example": "A laptop ships straight to a remote hire; on first sign-in, Windows Autopilot installs company apps and policies."}, {"type": "scenario", "prompt": "A new 4 TB drive must boot with Secure Boot enabled. Which partition scheme?", "choices": [{"id": "a", "text": "MBR"}, {"id": "b", "text": "GPT"}, {"id": "c", "text": "FAT32"}, {"id": "d", "text": "exFAT"}], "answer": "b", "why": "GPT supports drives over 2 TB and UEFI Secure Boot."}, {"type": "scenario", "prompt": "IT needs to image 60 lab PCs over the network at once. Which boot method?", "choices": [{"id": "a", "text": "USB"}, {"id": "b", "text": "Optical"}, {"id": "c", "text": "PXE"}, {"id": "d", "text": "Recovery partition"}], "answer": "c", "why": "PXE boots images over the network."}, {"type": "callout", "variant": "tip", "text": "Secure Boot or over 2 TB means GPT and UEFI. Mass imaging means PXE."}]'::jsonb where id = 'f485e1a2-b46b-475e-ab20-a5b41454b1b6';

-- Microsoft Windows Editions
update lessons set content_blocks = '[{"text": "Microsoft Windows Editions", "type": "title", "overview": "The Windows editions you''ll encounter in support work, and which features (domain join, BitLocker, Group Policy, Remote Desktop host) are edition-gated.", "examContext": "Why this matters: scenario questions often hinge on whether a described feature is even available on the edition in the scenario."}, {"type": "compare", "heading": "Home vs. Pro", "columns": ["Home", "Pro"], "rows": [{"label": "Domain join", "values": ["No", "Yes"]}, {"label": "Group Policy", "values": ["No", "Yes"]}, {"label": "BitLocker", "values": ["No (device encryption only)", "Yes"]}, {"label": "Remote Desktop host", "values": ["No", "Yes"]}, {"label": "Hyper-V", "values": ["No", "Yes"]}], "intro": "This one table answers most edition questions."}, {"type": "term_set", "heading": "Other editions", "terms": [{"term": "Pro for Workstations", "short": "High-end hardware: more RAM and CPUs, ReFS."}, {"term": "Enterprise", "short": "Volume licensed; advanced management and security such as AppLocker."}, {"term": "Education", "short": "Like Enterprise, licensed for schools."}]}, {"type": "key_term", "term": "Domain join", "definition": "Connects a PC to Active Directory for central logins and policy. Pro and above only.", "example": "A new hire''s laptop came with Home; it must be upgraded to Pro before it can join the company domain."}, {"type": "scenario", "prompt": "A small office wants to manage its PCs with Group Policy, but the option is missing on one machine. What''s the likely reason?", "choices": [{"id": "a", "text": "Outdated drivers"}, {"id": "b", "text": "It''s running Windows Home"}, {"id": "c", "text": "UAC is off"}, {"id": "d", "text": "BitLocker is enabled"}], "answer": "b", "why": "Home lacks Group Policy."}, {"type": "scenario", "prompt": "A user wants to connect to their office PC with Remote Desktop. The office PC runs Home. What''s needed?", "choices": [{"id": "a", "text": "A faster network"}, {"id": "b", "text": "Upgrade the office PC to Pro"}, {"id": "c", "text": "Enable BitLocker"}, {"id": "d", "text": "Install Hyper-V"}], "answer": "b", "why": "Home can''t host Remote Desktop sessions."}, {"type": "callout", "variant": "tip", "text": "Home lacks domain join, Group Policy, BitLocker, Remote Desktop host and Hyper-V. Pro has them all."}]'::jsonb where id = '0b8749eb-a068-4d1c-b211-42d6080bddc2';

-- Windows OS Features and Tools
update lessons set content_blocks = '[{"text": "Windows OS Features and Tools", "type": "title", "overview": "The built-in Windows GUI administrative tools a technician reaches for daily: process/performance monitoring, disk management, device management, and system configuration.", "examContext": "Why this matters: 220-1202 expects you to know which tool to open for a given task, and what that tool actually does."}, {"type": "compare", "heading": "Which tool for which job", "columns": ["Use it to"], "rows": [{"label": "Task Manager", "values": ["End processes, watch usage, manage startup apps"]}, {"label": "Device Manager", "values": ["Fix drivers; yellow warning icons"]}, {"label": "Disk Management", "values": ["Create, format, resize and letter volumes"]}, {"label": "Event Viewer", "values": ["Read Application, Security, System and Setup logs"]}, {"label": "Services", "values": ["Start, stop and set startup type for services"]}, {"label": "System Configuration (msconfig)", "values": ["Boot options like Safe Mode; startup and services"]}, {"label": "Task Scheduler", "values": ["Run programs on a time or trigger"]}, {"label": "Performance Monitor", "values": ["Track counters over time"]}, {"label": "Registry Editor (regedit)", "values": ["Edit low-level settings; back up first"]}, {"label": "MMC", "values": ["Host snap-ins in one console"]}]}, {"type": "key_term", "term": "Event Viewer", "definition": "The first stop for intermittent crashes and failed services.", "example": "A service fails every night at 2 a.m.; the System log shows it can''t reach a database that''s offline for backups."}, {"type": "scenario", "prompt": "A webcam shows a yellow warning icon and won''t work. Which tool?", "choices": [{"id": "a", "text": "Task Manager"}, {"id": "b", "text": "Device Manager"}, {"id": "c", "text": "Disk Management"}, {"id": "d", "text": "Event Viewer"}], "answer": "b", "why": "Driver and hardware problems live in Device Manager."}, {"type": "scenario", "prompt": "A PC slows down gradually over a week, and the technician wants to track CPU and disk counters over that time. Which tool?", "choices": [{"id": "a", "text": "Task Manager"}, {"id": "b", "text": "Performance Monitor"}, {"id": "c", "text": "msconfig"}, {"id": "d", "text": "Services"}], "answer": "b", "why": "Perfmon logs counters over time; Task Manager is a snapshot."}, {"type": "callout", "variant": "tip", "text": "Yellow icon: Device Manager. Runaway process: Task Manager. Intermittent crash: Event Viewer."}]'::jsonb where id = '985e3838-d481-45cb-b282-2c3d4301fcc6';

-- Microsoft Command-Line Tools
update lessons set content_blocks = '[{"text": "Microsoft Command-Line Tools", "type": "title", "overview": "The Windows Command Prompt and PowerShell utilities most commonly tested: networking diagnostics, disk/file management, and system information commands.", "examContext": "Why this matters: 220-1202 tests specific command syntax and purpose, expect scenario questions asking which single command solves a described problem."}, {"type": "compare", "heading": "Networking commands", "columns": ["Does"], "rows": [{"label": "ipconfig /all", "values": ["Full IP configuration and MAC for every adapter"]}, {"label": "ipconfig /flushdns", "values": ["Clears the local DNS cache"]}, {"label": "ping", "values": ["Tests reachability"]}, {"label": "tracert", "values": ["Shows each hop to a destination"]}, {"label": "netstat", "values": ["Lists connections and listening ports"]}, {"label": "nslookup", "values": ["Queries DNS directly"]}]}, {"type": "compare", "heading": "File, disk and system commands", "columns": ["Does"], "rows": [{"label": "dir", "values": ["Lists files and folders"]}, {"label": "chkdsk /f", "values": ["Finds and fixes filesystem errors and bad sectors"]}, {"label": "sfc /scannow", "values": ["Repairs corrupted Windows system files"]}, {"label": "diskpart", "values": ["Advanced partition and volume management"]}, {"label": "robocopy", "values": ["Robust copying with mirroring and retries"]}, {"label": "gpupdate /force", "values": ["Reapplies Group Policy now"]}]}, {"type": "key_term", "term": "PowerShell", "definition": "A scriptable shell using verb-noun cmdlets such as Get-Process. It does everything Command Prompt does and more.", "example": "Get-Service | Where-Object Status -eq Stopped lists every stopped service in one line."}, {"type": "compare", "heading": "sfc vs. chkdsk", "columns": ["sfc /scannow", "chkdsk"], "rows": [{"label": "Fixes", "values": ["Corrupted system files", "Filesystem errors and bad sectors"]}, {"label": "Symptom", "values": ["A Windows feature or DLL broke", "The drive won''t mount cleanly"]}]}, {"type": "scenario", "prompt": "After a website moved servers, one PC still goes to the old IP. Which command helps?", "choices": [{"id": "a", "text": "sfc /scannow"}, {"id": "b", "text": "ipconfig /flushdns"}, {"id": "c", "text": "chkdsk"}, {"id": "d", "text": "gpupdate /force"}], "answer": "b", "why": "Clear the stale DNS cache."}, {"type": "scenario", "prompt": "A Windows component stopped working after an abrupt shutdown and a system DLL seems corrupted. Which command?", "choices": [{"id": "a", "text": "chkdsk"}, {"id": "b", "text": "sfc /scannow"}, {"id": "c", "text": "diskpart"}, {"id": "d", "text": "robocopy"}], "answer": "b", "why": "sfc repairs protected system files."}, {"type": "callout", "variant": "tip", "text": "sfc fixes system files; chkdsk fixes the disk. flushdns clears stale name lookups."}]'::jsonb where id = '27ea3e65-9f2e-4de2-83d4-e3b699432698';

-- Configuring Windows Settings
update lessons set content_blocks = '[{"text": "Configuring Windows Settings", "type": "title", "overview": "The modern Settings app and legacy Control Panel, and the specific settings screens tested for user accounts, Windows Update, and power management.", "examContext": "Why this matters: 220-1202 tests where a specific configuration option lives, knowing the right applet or Settings page saves real time in a support call."}, {"type": "paragraph", "text": "Windows is moving settings from **Control Panel** into the **Settings** app. Both still exist, and some options live only in Control Panel."}, {"type": "compare", "heading": "Where settings live", "columns": ["What you''ll find"], "rows": [{"label": "Windows Update", "values": ["Install, pause and review updates"]}, {"label": "Power & Sleep", "values": ["Sleep timers and power plans"]}, {"label": "Accounts", "values": ["Local or Microsoft accounts, PIN and biometrics, account type"]}, {"label": "System > About", "values": ["Edition, version, build; rename PC or join a domain"]}, {"label": "Apps & Features", "values": ["Uninstall or modify apps"]}]}, {"type": "compare", "heading": "Standard vs. administrator account", "columns": ["Standard", "Administrator"], "rows": [{"label": "Can", "values": ["Use software, change personal settings", "Install software, change system settings, manage users"]}, {"label": "Best practice", "values": ["Daily use", "Elevate through UAC only when needed"]}]}, {"type": "scenario", "prompt": "A user with a Standard account can''t install a printer. What does this indicate?", "choices": [{"id": "a", "text": "A bug"}, {"id": "b", "text": "Expected behavior for a Standard account"}, {"id": "c", "text": "A failed update"}, {"id": "d", "text": "A bad driver"}], "answer": "b", "why": "Standard accounts can''t make system-wide changes."}, {"type": "scenario", "prompt": "Where does a technician check the exact Windows edition and build number?", "choices": [{"id": "a", "text": "Apps & Features"}, {"id": "b", "text": "System > About"}, {"id": "c", "text": "Power & Sleep"}, {"id": "d", "text": "Windows Update history"}], "answer": "b", "why": "About shows edition, version and build."}, {"type": "callout", "variant": "tip", "text": "Standard for daily work, admin only when needed. Edition and build are in System > About."}]'::jsonb where id = '639cd7a0-ceda-4276-87ba-1f33ed4ed88b';

-- Configuring Windows Networking Features
update lessons set content_blocks = '[{"text": "Configuring Windows Networking Features", "type": "title", "overview": "How to configure a Windows PC''s network identity, sharing settings, firewall rules, and VPN connections.", "examContext": "Why this matters: 220-1202 tests network configuration in the context of Windows specifically, distinct from the general networking hardware covered on Core 1."}, {"type": "compare", "heading": "Network profiles", "columns": ["Public", "Private", "Domain"], "rows": [{"label": "Trust", "values": ["Untrusted", "Trusted", "Managed by Active Directory"]}, {"label": "Discovery and sharing", "values": ["Off", "On", "Set by domain policy"]}, {"label": "Use for", "values": ["Cafés, airports", "Home, small office", "Joined corporate networks"]}]}, {"type": "term_set", "heading": "Configuring the connection", "terms": [{"term": "Windows Defender Firewall", "short": "Inbound and outbound rules per app or port, per profile."}, {"term": "File and Printer Sharing", "short": "Must be enabled, usually only on Private."}, {"term": "Built-in VPN client", "short": "IKEv2 or L2TP/IPsec; needs server address, type and credentials. Avoid PPTP."}]}, {"type": "scenario", "prompt": "File sharing works at home but not when the laptop is at a coffee shop. What''s the likely reason?", "choices": [{"id": "a", "text": "Firewall corruption"}, {"id": "b", "text": "The coffee shop network is on the Public profile"}, {"id": "c", "text": "A bad NIC"}, {"id": "d", "text": "DNS failure"}], "answer": "b", "why": "Public profiles turn off discovery and sharing, by design."}, {"type": "scenario", "prompt": "Which VPN protocol should be avoided as legacy and insecure?", "choices": [{"id": "a", "text": "IKEv2"}, {"id": "b", "text": "L2TP/IPsec"}, {"id": "c", "text": "PPTP"}, {"id": "d", "text": "SSL VPN"}], "answer": "c", "why": "PPTP is outdated and weak."}, {"type": "callout", "variant": "tip", "text": "Sharing works at home but not in public: it''s the network profile, not the firewall."}]'::jsonb where id = '419442e3-deb4-48bd-b15c-bc3db9bc8a57';

-- macOS Features and Tools
update lessons set content_blocks = '[{"text": "macOS Features and Tools", "type": "title", "overview": "The macOS-specific tools and concepts a technician needs: file management, backup, disk tools, credential storage, and app security gating.", "examContext": "Why this matters: 220-1202 expects familiarity with macOS terminology and tools even for technicians primarily supporting Windows."}, {"type": "compare", "heading": "macOS and its Windows equivalent", "columns": ["macOS", "Windows"], "rows": [{"label": "File manager", "values": ["Finder", "File Explorer"]}, {"label": "Backup", "values": ["Time Machine", "File History, Backup"]}, {"label": "Disk tools", "values": ["Disk Utility", "Disk Management plus chkdsk"]}, {"label": "Full-disk encryption", "values": ["FileVault", "BitLocker"]}, {"label": "Credential storage", "values": ["Keychain", "Credential Manager"]}, {"label": "Search", "values": ["Spotlight (Cmd+Space)", "Windows Search"]}]}, {"type": "key_term", "term": "Gatekeeper", "definition": "Checks that downloaded apps are signed and notarized by Apple before they run.", "example": "A user downloads an unsigned utility and macOS refuses to open it until they explicitly override."}, {"type": "term_set", "heading": "Also know", "terms": [{"term": "Mission Control", "short": "Virtual desktops (Spaces) and every open window."}, {"term": "Software Update", "short": "System Settings > General > Software Update."}, {"term": "Terminal", "short": "Unix commands such as ls, cd, grep and chmod work as in Linux."}]}, {"type": "scenario", "prompt": "What''s the macOS equivalent of BitLocker?", "choices": [{"id": "a", "text": "Keychain"}, {"id": "b", "text": "FileVault"}, {"id": "c", "text": "Gatekeeper"}, {"id": "d", "text": "Time Machine"}], "answer": "b", "why": "FileVault is full-disk encryption."}, {"type": "scenario", "prompt": "A Mac blocks an app downloaded from a random website from opening. Which feature did this?", "choices": [{"id": "a", "text": "Spotlight"}, {"id": "b", "text": "Gatekeeper"}, {"id": "c", "text": "Mission Control"}, {"id": "d", "text": "Disk Utility"}], "answer": "b", "why": "Gatekeeper blocks unsigned or unnotarized apps."}, {"type": "callout", "variant": "tip", "text": "Know the pairs: FileVault and BitLocker, Time Machine and backup, Keychain and Credential Manager."}]'::jsonb where id = '9fcc8425-b5f5-4476-9fc5-37f4f10102ff';

-- Linux Features and Tools
update lessons set content_blocks = '[{"text": "Linux Features and Tools", "type": "title", "overview": "Fundamental Linux command-line tools for navigation, permissions, process management, and package installation.", "examContext": "Why this matters: 220-1202 expects you to know common Linux commands and the permission model, even though the exam doesn''t test any single distribution deeply."}, {"type": "compare", "heading": "Common Linux commands", "columns": ["Does"], "rows": [{"label": "ls (ls -l)", "values": ["List files (detailed)"]}, {"label": "cd / pwd", "values": ["Change directory / show current directory"]}, {"label": "grep", "values": ["Search text for a pattern"]}, {"label": "sudo", "values": ["Run one command as root"]}, {"label": "ps / top", "values": ["List processes / live view"]}, {"label": "chmod / chown", "values": ["Change permissions / ownership"]}]}, {"type": "compare", "heading": "Reading numeric permissions", "columns": ["Owner", "Group", "Others"], "rows": [{"label": "chmod 755", "values": ["rwx (7)", "r-x (5)", "r-x (5)"]}, {"label": "chmod 644", "values": ["rw- (6)", "r-- (4)", "r-- (4)"]}], "intro": "Read is 4, write is 2, execute is 1. Add them for each set."}, {"type": "term_set", "heading": "Packages and scripts", "terms": [{"term": "apt", "short": "Debian and Ubuntu package manager."}, {"term": "dnf", "short": "Red Hat and Fedora; replaced yum."}, {"term": "Shebang", "short": "#!/bin/bash on line one picks the interpreter."}, {"term": "root", "short": "The superuser; sudo borrows its rights for one command."}]}, {"type": "scenario", "prompt": "A script needs to be runnable by everyone but writable only by its owner. Which permission?", "choices": [{"id": "a", "text": "644"}, {"id": "b", "text": "755"}, {"id": "c", "text": "777"}, {"id": "d", "text": "600"}], "answer": "b", "why": "Owner rwx, group and others r-x."}, {"type": "scenario", "prompt": "Which command installs a package on Ubuntu?", "choices": [{"id": "a", "text": "dnf install"}, {"id": "b", "text": "apt install"}, {"id": "c", "text": "yum install"}, {"id": "d", "text": "chmod install"}], "answer": "b", "why": "Ubuntu uses apt."}, {"type": "callout", "variant": "tip", "text": "755 is rwx r-x r-x; 644 is rw- r-- r--. apt for Ubuntu, dnf for Red Hat."}]'::jsonb where id = '95de2fbd-80df-4739-b309-a602d6f0fc0a';

-- Installing Applications
update lessons set content_blocks = '[{"text": "Installing Applications", "type": "title", "overview": "How applications get installed across Windows, macOS, and Linux, and the compatibility/licensing checks a technician should perform first.", "examContext": "Why this matters: 220-1202 tests the practical checklist a technician runs through before and during software installation."}, {"type": "diagram", "heading": "Before and during an install", "diagram": {"kind": "flow", "steps": [{"label": "Check requirements", "note": "OS version, disk, RAM, CPU architecture."}, {"label": "Verify the source", "note": "Official site or store; check signature or hash."}, {"label": "Confirm licensing", "note": "Per device, per user, volume, subscription or perpetual."}, {"label": "Choose the method", "note": "Installer, store, package manager or network deployment."}, {"label": "Restart if required"}]}}, {"type": "compare", "heading": "Installation methods by OS", "columns": ["Methods"], "rows": [{"label": "Windows", "values": [".exe and .msi installers, Microsoft Store, winget"]}, {"label": "macOS", "values": [".dmg images dragged to Applications, Mac App Store"]}, {"label": "Linux", "values": ["apt or dnf from repositories, .deb or .rpm packages"]}]}, {"type": "key_term", "term": "Dependencies", "definition": "Some apps need a separate runtime or framework installed first.", "example": "An app fails with \"VCRUNTIME140.dll was not found\" until the Visual C++ redistributable is installed."}, {"type": "scenario", "prompt": "A new app won''t start and reports a missing .NET runtime. What should the technician do?", "choices": [{"id": "a", "text": "Reinstall Windows"}, {"id": "b", "text": "Install the required runtime first"}, {"id": "c", "text": "Run chkdsk"}, {"id": "d", "text": "Switch to a Standard account"}], "answer": "b", "why": "Install the missing dependency."}, {"type": "scenario", "prompt": "Before installing design software on 40 PCs, what should be confirmed besides hardware requirements?", "choices": [{"id": "a", "text": "Licensing covers 40 devices or users"}, {"id": "b", "text": "The PCs use exFAT"}, {"id": "c", "text": "BitLocker is off"}, {"id": "d", "text": "PXE is enabled"}], "answer": "a", "why": "Licensing is part of the checklist."}, {"type": "callout", "variant": "tip", "text": "Requirements, source, licensing, method, restart. Missing runtime errors mean a dependency."}]'::jsonb where id = 'cee7f78f-8f8d-4b25-8073-94a3a111f23b';

-- Installing and Configuring Cloud-Based Productivity Tools
update lessons set content_blocks = '[{"text": "Installing and Configuring Cloud-Based Productivity Tools", "type": "title", "overview": "Cloud office suites, hosted email/calendar, and file-sync clients, configuration steps and common troubleshooting points.", "examContext": "Why this matters: 220-1202''s Domain 1 closes with cloud-based productivity tools, reflecting how much day-to-day IT support now involves SaaS applications rather than only local software."}, {"type": "compare", "heading": "Cloud productivity suites", "columns": ["Microsoft 365", "Google Workspace"], "rows": [{"label": "Email", "values": ["Exchange Online", "Gmail"]}, {"label": "Documents", "values": ["Office apps", "Docs, Sheets, Slides"]}, {"label": "Files", "values": ["OneDrive", "Google Drive"]}, {"label": "Chat and meetings", "values": ["Teams", "Chat and Meet"]}]}, {"type": "key_term", "term": "Modern authentication (OAuth 2.0)", "definition": "The mail client gets a token after the user signs in on the provider''s page, instead of storing a password. Supports MFA.", "example": "Outlook opens a Microsoft sign-in window with an authenticator prompt rather than asking for a password in a dialog."}, {"type": "key_term", "term": "Files On-Demand", "definition": "Cloud files appear in File Explorer or Finder but download only when opened.", "example": "A 2 TB OneDrive shows every folder on a 256 GB laptop, because most files are placeholders."}, {"type": "term_set", "heading": "Sync options", "terms": [{"term": "Selective sync", "short": "Only chosen folders sync locally."}, {"term": "Full sync", "short": "Everything is stored locally."}]}, {"type": "scenario", "prompt": "A user says OneDrive files appear in File Explorer but take a moment to open and need internet. What''s happening?", "choices": [{"id": "a", "text": "A sync error"}, {"id": "b", "text": "Files On-Demand working normally"}, {"id": "c", "text": "Disk corruption"}, {"id": "d", "text": "A malware infection"}], "answer": "b", "why": "That''s normal placeholder behavior."}, {"type": "scenario", "prompt": "Why do modern email setups use OAuth instead of a stored password?", "choices": [{"id": "a", "text": "It''s faster"}, {"id": "b", "text": "It''s more secure and supports MFA"}, {"id": "c", "text": "It works without internet"}, {"id": "d", "text": "POP3 requires it"}], "answer": "b", "why": "Tokens replace stored passwords."}, {"type": "callout", "variant": "tip", "text": "Files that appear but download when opened: Files On-Demand. Modern authentication uses tokens and supports MFA."}]'::jsonb where id = 'e7e7ad6a-c8ff-4f70-93f4-017304d4f3e8';

-- Domain 1 Recap: Operating Systems
update lessons set content_blocks = '[{"text": "Domain 1 Recap: Operating Systems", "type": "title", "overview": "The highest-yield facts from all 11 Operating Systems lessons, gathered in one place before the domain checkpoint.", "examContext": "Why this matters: this recap is ungraded, read it as a final consolidation pass before you attempt the 33-question checkpoint."}, {"type": "term_set", "heading": "Installs and editions", "terms": [{"term": "Filesystems", "short": "NTFS, exFAT (cross-platform), ReFS, APFS, ext4, XFS."}, {"term": "Install types", "short": "In-place, clean, repair, multiboot."}, {"term": "GPT + UEFI", "short": "Secure Boot and drives over 2 TB."}, {"term": "PXE / zero-touch", "short": "Network imaging / self-provisioning."}, {"term": "Home lacks", "short": "Domain join, Group Policy, BitLocker, RDP host, Hyper-V."}]}, {"type": "term_set", "heading": "Windows tools", "terms": [{"term": "Device Manager", "short": "Drivers."}, {"term": "Event Viewer", "short": "Logs."}, {"term": "sfc / chkdsk", "short": "System files / disk."}, {"term": "ipconfig /flushdns", "short": "Clear DNS cache."}, {"term": "gpupdate /force", "short": "Reapply policy now."}, {"term": "Public / Private profile", "short": "Sharing off / on."}]}, {"type": "term_set", "heading": "macOS, Linux and apps", "terms": [{"term": "FileVault, Keychain, Gatekeeper", "short": "Encryption, credentials, app verification."}, {"term": "chmod 755 / 644", "short": "rwx r-x r-x / rw- r-- r--."}, {"term": "apt / dnf", "short": "Ubuntu / Red Hat."}, {"term": "OAuth", "short": "Tokens and MFA."}, {"term": "Files On-Demand", "short": "Downloads when opened."}]}, {"type": "scenario", "prompt": "Which Windows edition can join a domain?", "choices": [{"id": "a", "text": "Home"}, {"id": "b", "text": "Pro"}, {"id": "c", "text": "Both"}, {"id": "d", "text": "Neither"}], "answer": "b", "why": "Pro and above."}, {"type": "scenario", "prompt": "Which command repairs corrupted system files?", "choices": [{"id": "a", "text": "chkdsk"}, {"id": "b", "text": "sfc /scannow"}, {"id": "c", "text": "diskpart"}, {"id": "d", "text": "ipconfig"}], "answer": "b", "why": "System File Checker."}, {"type": "scenario", "prompt": "What''s the macOS equivalent of Credential Manager?", "choices": [{"id": "a", "text": "Finder"}, {"id": "b", "text": "Keychain"}, {"id": "c", "text": "Spotlight"}, {"id": "d", "text": "FileVault"}], "answer": "b", "why": "Keychain."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = 'e79c45c0-b491-4e05-a4da-b401d99f7e58';

-- Security Measures and Their Purposes
update lessons set content_blocks = '[{"text": "Security Measures and Their Purposes", "type": "title", "overview": "Physical security controls, authentication factor categories, and Zero Trust, the security mindset underlying the rest of this domain.", "examContext": "Why this matters: Domain 2 opens with the foundational vocabulary (Zero Trust, MFA factors, physical controls) that every later lesson in this domain builds on."}, {"type": "compare", "heading": "Physical security controls", "columns": ["Purpose"], "rows": [{"label": "Badge reader, access control vestibule (mantrap)", "values": ["Only authorized people get in; one door closes before the next opens"]}, {"label": "Biometric lock", "values": ["Fingerprint, retina or face to open a door or device"]}, {"label": "Guards and cameras", "values": ["Deter and monitor"]}, {"label": "Cable lock", "values": ["Stops a laptop walking away"]}, {"label": "Locking cabinet or rack", "values": ["Restricts access to equipment"]}]}, {"type": "key_term", "term": "Zero trust", "definition": "Never trust, always verify. No user or device is trusted by default, even inside the network; every request is checked against identity, device health and context.", "example": "An employee in the office still has to pass MFA and a device check to open the HR system."}, {"type": "diagram", "heading": "MFA factor categories", "diagram": {"kind": "triad", "points": [{"label": "Something you know", "note": "Password, PIN."}, {"label": "Something you have", "note": "Security key, authenticator app, smart card."}, {"label": "Something you are", "note": "Fingerprint, face."}], "center": "pick two or more"}, "caption": "Two passwords isn''t MFA: both are something you know. Passwordless removes the knowledge factor altogether."}, {"type": "scenario", "prompt": "A login asks for a password and then the answer to a security question. Why isn''t this MFA?", "choices": [{"id": "a", "text": "Security questions are too easy"}, {"id": "b", "text": "Both are something you know"}, {"id": "c", "text": "It needs biometrics specifically"}, {"id": "d", "text": "It needs a location check"}], "answer": "b", "why": "MFA needs different categories."}, {"type": "scenario", "prompt": "Which describes continuous verification regardless of network location?", "choices": [{"id": "a", "text": "Defense in depth"}, {"id": "b", "text": "Zero trust"}, {"id": "c", "text": "Least privilege"}, {"id": "d", "text": "Perimeter security"}], "answer": "b", "why": "Never trust, always verify."}, {"type": "callout", "variant": "tip", "text": "Two of the same factor isn''t MFA. \"Never trust, always verify\" is zero trust."}]'::jsonb where id = '1662069d-a3b9-4c2d-bcc1-5a2c4f9a1c66';

-- Windows OS Security Settings
update lessons set content_blocks = '[{"text": "Windows OS Security Settings", "type": "title", "overview": "The Windows-specific security controls a technician configures: user/group permissions, NTFS vs. share permissions, built-in antivirus/firewall, encryption, and UAC.", "examContext": "Why this matters: 220-1202 tests how Windows enforces access control at the OS level, distinct from network-level security."}, {"type": "term_set", "heading": "Core Windows security controls", "terms": [{"term": "Local Users and Groups", "short": "Accounts and group membership, such as Administrators and Users."}, {"term": "Defender Antivirus", "short": "Built-in real-time malware protection."}, {"term": "Defender Firewall", "short": "Host-based firewall."}, {"term": "UAC", "short": "Prompts before any elevated action."}, {"term": "gpedit.msc", "short": "Local Group Policy on a non-domain PC."}]}, {"type": "compare", "heading": "NTFS vs. share permissions", "columns": ["NTFS", "Share"], "rows": [{"label": "Applies", "values": ["Locally and over the network", "Only over the network"]}, {"label": "Levels", "values": ["Read, Write, Modify, Full Control", "Read, Change, Full Control"]}], "intro": "Over the network, the **most restrictive** combination wins."}, {"type": "key_term", "term": "Effective permission example", "definition": "Share set to Read, NTFS set to Full Control. Over the network the user gets Read.", "example": "A manager can edit a file at her own desk but only read it when opening the same folder from another PC through the share."}, {"type": "compare", "heading": "BitLocker vs. EFS", "columns": ["BitLocker", "EFS"], "rows": [{"label": "Encrypts", "values": ["The whole volume", "Individual files and folders"]}, {"label": "Tied to", "values": ["The device, often with TPM", "A specific user account"]}]}, {"type": "scenario", "prompt": "A folder''s share permission is Change and its NTFS permission is Read. What can a network user do?", "choices": [{"id": "a", "text": "Change"}, {"id": "b", "text": "Read"}, {"id": "c", "text": "Full Control"}, {"id": "d", "text": "Nothing"}], "answer": "b", "why": "The more restrictive of the two applies."}, {"type": "scenario", "prompt": "A user wants to encrypt one sensitive folder so only their account can open it. Which feature?", "choices": [{"id": "a", "text": "BitLocker"}, {"id": "b", "text": "EFS"}, {"id": "c", "text": "UAC"}, {"id": "d", "text": "Defender Firewall"}], "answer": "b", "why": "EFS encrypts per file or folder, tied to the user."}, {"type": "callout", "variant": "tip", "text": "Network access: the more restrictive of share and NTFS wins. BitLocker is the whole disk; EFS is per file."}]'::jsonb where id = '3304a191-b275-4ca3-890f-dca60bb7121f';

-- Wireless Security Protocols and Authentication Methods
update lessons set content_blocks = '[{"text": "Wireless Security Protocols and Authentication Methods", "type": "title", "overview": "Wi-Fi encryption standards from WEP through WPA3, enterprise authentication via RADIUS/802.1X, and modern passwordless authentication standards.", "examContext": "Why this matters: 220-1202 tests wireless security and adds passwordless authentication methods (FIDO2, TOTP, SAML) as newer content compared to the retired exam."}, {"type": "diagram", "heading": "Wi-Fi security over time", "diagram": {"kind": "ladder", "rungs": [{"label": "WPA3", "note": "Current; SAE resists offline password guessing."}, {"label": "WPA2", "note": "AES-CCMP; baseline minimum."}, {"label": "WPA", "note": "TKIP; outdated."}, {"label": "WEP", "note": "Obsolete; never use.", "muted": true}], "top": "strongest", "bottom": "weakest"}}, {"type": "compare", "heading": "Personal vs. Enterprise mode", "columns": ["Personal (PSK)", "Enterprise (802.1X / RADIUS)"], "rows": [{"label": "Credentials", "values": ["One shared passphrase for everyone", "Each user''s own login"]}, {"label": "Fits", "values": ["Home and SOHO", "Businesses"]}, {"label": "Revoking one person", "values": ["Change the password for everyone", "Disable that user''s account"]}], "cue": ["\"One Wi-Fi password\"", "\"Each employee logs in\""]}, {"type": "compare", "heading": "Modern authentication standards", "columns": ["What it does"], "rows": [{"label": "FIDO2", "values": ["Passwordless login with a security key or built-in authenticator; resists phishing"]}, {"label": "TOTP", "values": ["A new code every 30 to 60 seconds from an authenticator app"]}, {"label": "SAML", "values": ["Single sign-on: log in once with an identity provider, reach many apps"]}]}, {"type": "scenario", "prompt": "Each employee signs into the office Wi-Fi with their own username and password. Which mode?", "choices": [{"id": "a", "text": "WPA2-Personal"}, {"id": "b", "text": "WPA3-Enterprise with 802.1X"}, {"id": "c", "text": "WEP"}, {"id": "d", "text": "Open network"}], "answer": "b", "why": "Per-user credentials mean Enterprise mode."}, {"type": "scenario", "prompt": "Which method logs in with a hardware key and no password, and resists phishing?", "choices": [{"id": "a", "text": "TOTP"}, {"id": "b", "text": "FIDO2"}, {"id": "c", "text": "SAML"}, {"id": "d", "text": "PSK"}], "answer": "b", "why": "FIDO2 uses public-key cryptography with no shared secret."}, {"type": "callout", "variant": "tip", "text": "Shared password: Personal. Individual logins: Enterprise. FIDO2 is passwordless; SAML is single sign-on."}]'::jsonb where id = 'c2b2f7b3-93b4-48c9-bbe7-776300b5e75b';

-- Malware Types and Detection, Removal, and Prevention
update lessons set content_blocks = '[{"text": "Malware Types and Detection, Removal, and Prevention", "type": "title", "overview": "The malware categories tested on 220-1202, including newer types like fileless malware and cryptominers, plus core detection/removal/prevention practices.", "examContext": "Why this matters: this exam version adds fileless malware and cryptominers to the malware objectives, reflecting current threat trends."}, {"type": "compare", "heading": "Malware categories", "columns": ["Defining trait"], "rows": [{"label": "Virus", "values": ["Attaches to a file; needs user action to spread"]}, {"label": "Worm", "values": ["Spreads across networks by itself"]}, {"label": "Trojan", "values": ["Disguised as legitimate software"]}, {"label": "Ransomware", "values": ["Encrypts files and demands payment"]}, {"label": "Spyware / keylogger", "values": ["Watches activity or records keystrokes"]}, {"label": "Rootkit", "values": ["Hides deep in the OS to conceal itself and others"]}, {"label": "Fileless malware", "values": ["Lives in memory, abusing tools like PowerShell"]}, {"label": "Cryptominer", "values": ["Uses your CPU or GPU to mine cryptocurrency"]}]}, {"type": "key_term", "term": "Fileless malware", "definition": "Never writes a normal executable to disk; runs in memory using trusted tools, so signature scanners have nothing to scan.", "example": "A malicious macro launches PowerShell, which downloads and runs code directly in memory."}, {"type": "term_set", "heading": "Detection and prevention", "terms": [{"term": "Signature antivirus", "short": "Matches known patterns."}, {"term": "Heuristic or behavioral", "short": "Flags suspicious behavior, even from unknown malware."}, {"term": "EDR", "short": "Endpoint monitoring and response."}, {"term": "Prevention", "short": "Patching, least privilege, email and web filtering, user education."}]}, {"type": "scenario", "prompt": "An idle PC''s fans roar and the GPU sits near 100% with no obvious app running. What''s the likely cause?", "choices": [{"id": "a", "text": "Ransomware"}, {"id": "b", "text": "Cryptominer"}, {"id": "c", "text": "Rootkit"}, {"id": "d", "text": "Keylogger"}], "answer": "b", "why": "Sustained, unexplained CPU or GPU load points to cryptojacking."}, {"type": "scenario", "prompt": "Malware infects one PC and then spreads to others on the network without anyone clicking anything. What type?", "choices": [{"id": "a", "text": "Virus"}, {"id": "b", "text": "Worm"}, {"id": "c", "text": "Trojan"}, {"id": "d", "text": "Spyware"}], "answer": "b", "why": "Self-propagation defines a worm."}, {"type": "callout", "variant": "tip", "text": "Worms spread themselves; viruses need help. No file on disk, uses PowerShell: fileless."}]'::jsonb where id = 'bed3d0f1-c8c0-4ae7-bd58-8d0affe8b480';

-- Social Engineering Attacks and Vulnerabilities
update lessons set content_blocks = '[{"text": "Social Engineering Attacks and Vulnerabilities", "type": "title", "overview": "The human-targeted attack techniques, phishing and its variants, pretexting, shoulder surfing, tailgating, and why they work.", "examContext": "Why this matters: social engineering is consistently one of the most heavily scenario-tested areas of the Security domain."}, {"type": "compare", "heading": "Phishing by channel and target", "columns": ["Channel or target"], "rows": [{"label": "Phishing", "values": ["Email"]}, {"label": "Spear phishing", "values": ["A specific person, with personal details"]}, {"label": "Whaling", "values": ["Executives"]}, {"label": "Vishing", "values": ["Phone call"]}, {"label": "Smishing", "values": ["SMS text"]}]}, {"type": "term_set", "heading": "In-person and other techniques", "terms": [{"term": "Pretexting", "short": "A made-up scenario or identity."}, {"term": "Shoulder surfing", "short": "Watching someone type credentials."}, {"term": "Tailgating", "short": "Following someone through a secure door."}, {"term": "Dumpster diving", "short": "Searching discarded paperwork."}, {"term": "Spoofing", "short": "Faking a sender, caller ID or website."}]}, {"type": "key_term", "term": "Business email compromise (BEC)", "definition": "Impersonating an executive or vendor by email to get a payment or data.", "example": "\"The CEO\" emails payroll asking to change her direct deposit account before Friday."}, {"type": "callout", "variant": "info", "text": "Social engineering works through **urgency**, **authority**, **trust** and **fear**. A message that leans on these is a warning sign."}, {"type": "scenario", "prompt": "A caller claiming to be from the bank asks an employee to read back a one-time code. Which technique?", "choices": [{"id": "a", "text": "Smishing"}, {"id": "b", "text": "Vishing"}, {"id": "c", "text": "Whaling"}, {"id": "d", "text": "Tailgating"}], "answer": "b", "why": "Voice phishing."}, {"type": "scenario", "prompt": "A spear phishing email targets the company''s CFO specifically. What''s the more specific term?", "choices": [{"id": "a", "text": "Smishing"}, {"id": "b", "text": "Whaling"}, {"id": "c", "text": "Pretexting"}, {"id": "d", "text": "Spoofing"}], "answer": "b", "why": "Targeting executives is whaling."}, {"type": "callout", "variant": "tip", "text": "Phishing email, vishing voice, smishing SMS. Whaling targets executives."}]'::jsonb where id = 'd036ba77-d5bc-4454-9bcf-d7578a2f4972';

-- SOHO Malware Removal Procedures
update lessons set content_blocks = '[{"text": "SOHO Malware Removal Procedures", "type": "title", "overview": "CompTIA''s standard malware removal sequence for a small office/home office environment, and why the order of steps matters.", "examContext": "Why this matters: this exact 7-step order is one of the most reliably tested sequences on the entire A+ certification."}, {"type": "diagram", "heading": "The malware removal process", "diagram": {"kind": "flow", "steps": [{"label": "Investigate and verify", "note": "Confirm it''s really malware."}, {"label": "Quarantine", "note": "Disconnect from the network."}, {"label": "Disable System Restore", "note": "So malware isn''t saved in restore points."}, {"label": "Remediate", "note": "Update anti-malware, scan, remove; Safe Mode or a boot environment if needed."}, {"label": "Schedule scans and updates"}, {"label": "Re-enable System Restore", "note": "Create a clean restore point."}, {"label": "Educate the user"}]}, "caption": "One of the most reliably tested sequences on all of A+."}, {"type": "key_term", "term": "Quarantine", "definition": "Two meanings: isolating an infected system from the network, and an anti-malware tool moving a file into isolated storage instead of deleting it.", "example": "The scanner quarantines a suspicious DLL; it turns out to be a false positive, so it''s restored."}, {"type": "scenario", "prompt": "A technician confirms a PC is infected. What''s the next step?", "choices": [{"id": "a", "text": "Disable System Restore"}, {"id": "b", "text": "Quarantine the system from the network"}, {"id": "c", "text": "Run a full scan"}, {"id": "d", "text": "Educate the user"}], "answer": "b", "why": "Isolate before anything else so it can''t spread."}, {"type": "scenario", "prompt": "Why disable System Restore before removing malware?", "choices": [{"id": "a", "text": "It speeds up scans"}, {"id": "b", "text": "So the malware isn''t kept in restore points"}, {"id": "c", "text": "It''s required for Safe Mode"}, {"id": "d", "text": "To free disk space"}], "answer": "b", "why": "Otherwise a later restore could bring the malware back."}, {"type": "callout", "variant": "tip", "text": "Investigate, quarantine, disable restore, remediate, schedule, re-enable restore, educate."}]'::jsonb where id = '9fe09142-8a87-4842-a1eb-935d8be485e5';

-- Workstation Security Options and Hardening
update lessons set content_blocks = '[{"text": "Workstation Security Options and Hardening", "type": "title", "overview": "Password and login policies, account lockout, and modern endpoint threat detection categories (EDR, MDR, XDR) plus data loss prevention (DLP).", "examContext": "Why this matters: EDR/MDR/XDR and DLP are newer, heavily emphasized additions on 220-1202''s Security domain."}, {"type": "term_set", "heading": "Login and account hardening", "terms": [{"term": "Password length and complexity", "short": "Resists guessing and cracking."}, {"term": "Account lockout", "short": "Locks after failed attempts; slows brute force."}, {"term": "Screen lock timeout", "short": "Locks idle sessions."}, {"term": "Disable or rename default accounts", "short": "Guest and built-in Administrator are common targets."}, {"term": "Least privilege", "short": "Only the access each user needs."}]}, {"type": "compare", "heading": "EDR vs. XDR vs. MDR", "columns": ["EDR", "XDR", "MDR"], "rows": [{"label": "What it is", "values": ["Endpoint monitoring and response tool", "Correlation across endpoint, network, email and cloud", "A managed service: people watching and responding"]}, {"label": "Example", "values": ["Isolates a laptop and kills a process", "Links a phishing email to a later endpoint alert", "An outside SOC handles alerts overnight"]}]}, {"type": "key_term", "term": "Data loss prevention (DLP)", "definition": "Monitors and blocks sensitive data leaving by email, USB or cloud upload.", "example": "An email with 50 credit card numbers in an attachment is blocked before it leaves the company."}, {"type": "scenario", "prompt": "A company without its own security team pays a provider to watch its endpoint alerts around the clock and respond. What is this?", "choices": [{"id": "a", "text": "EDR"}, {"id": "b", "text": "XDR"}, {"id": "c", "text": "MDR"}, {"id": "d", "text": "DLP"}], "answer": "c", "why": "MDR is a managed service run by people."}, {"type": "scenario", "prompt": "An attacker tries thousands of passwords against one account. Which policy slows this down most directly?", "choices": [{"id": "a", "text": "Screen lock"}, {"id": "b", "text": "Account lockout"}, {"id": "c", "text": "DLP"}, {"id": "d", "text": "Least privilege"}], "answer": "b", "why": "Lockout stops repeated guessing."}, {"type": "callout", "variant": "tip", "text": "EDR is the endpoint tool, XDR correlates across sources, MDR is a team. DLP stops data leaving."}]'::jsonb where id = 'e61423e7-648b-4112-9f6d-44947c274b25';

-- Securing Mobile Devices
update lessons set content_blocks = '[{"text": "Securing Mobile Devices", "type": "title", "overview": "The security controls specific to phones and tablets: authentication methods, remote management, and app-source restrictions.", "examContext": "Why this matters: mobile security overlaps with but is distinct from workstation security, and MDM is a core tested concept."}, {"type": "term_set", "heading": "Mobile security controls", "terms": [{"term": "Screen lock", "short": "PIN, pattern or biometric; the first line of defense."}, {"term": "Remote wipe", "short": "Through MDM or the vendor''s find-my-device service."}, {"term": "Full-device encryption", "short": "On by default on current iOS and Android."}, {"term": "Failed-login wipe", "short": "Erases or locks after too many wrong attempts."}, {"term": "Locator apps", "short": "Find, lock or wipe a lost device."}]}, {"type": "key_term", "term": "MDM", "definition": "Enrolls and manages devices: enforces lock and encryption, restricts apps, pushes profiles, and wipes lost or departed employees'' devices.", "example": "A new phone receives Wi-Fi, email and VPN settings automatically the moment it''s enrolled."}, {"type": "compare", "heading": "iOS vs. Android app sources", "columns": ["iOS", "Android"], "rows": [{"label": "Default source", "values": ["App Store, reviewed by Apple", "Google Play"]}, {"label": "Sideloading", "values": ["Tightly restricted", "Allowed more readily"]}, {"label": "Risk", "values": ["Lower", "Higher if users bypass warnings"]}]}, {"type": "key_term", "term": "Containerization", "definition": "Separates work and personal data on a BYOD device, so IT can wipe only the work side.", "example": "An employee leaves; IT removes company email and apps, while personal photos stay untouched."}, {"type": "scenario", "prompt": "An employee leaves and IT removes only the company email and apps from their personal phone. What made this possible?", "choices": [{"id": "a", "text": "Full device wipe"}, {"id": "b", "text": "MDM with containerization"}, {"id": "c", "text": "Locator app"}, {"id": "d", "text": "Sideloading"}], "answer": "b", "why": "Selective wipe of the work container."}, {"type": "scenario", "prompt": "Which is the first line of defense if a phone is lost?", "choices": [{"id": "a", "text": "Remote wipe"}, {"id": "b", "text": "Screen lock"}, {"id": "c", "text": "Locator app"}, {"id": "d", "text": "Encryption"}], "answer": "b", "why": "It stops casual access immediately."}, {"type": "callout", "variant": "tip", "text": "Wipe only work data from a personal phone: MDM with containerization."}]'::jsonb where id = '58af8634-941b-4253-81b7-792e2113716f';

-- Data Destruction and Disposal Methods
update lessons set content_blocks = '[{"text": "Data Destruction and Disposal Methods", "type": "title", "overview": "How to properly and permanently destroy data on storage media before disposal, resale, or recycling.", "examContext": "Why this matters: choosing the wrong disposal method for a drive that must never be recovered is a real compliance and security failure."}, {"type": "compare", "heading": "Destruction methods", "columns": ["Works on", "Assurance"], "rows": [{"label": "Shredding", "values": ["Any media", "Highest; unrecoverable"]}, {"label": "Incineration", "values": ["Any media", "Highest-security requirements"]}, {"label": "Drilling or hammering", "values": ["Any media", "Lower; less thorough"]}, {"label": "Degaussing", "values": ["Magnetic media (HDDs) only", "High for HDDs; does nothing to SSDs"]}, {"label": "Secure wipe", "values": ["Any drive", "Overwrites every sector; drive can be reused"]}]}, {"type": "key_term", "term": "Delete or format isn''t erasure", "definition": "Deleting or formatting removes the filesystem''s pointers, leaving data recoverable until it''s overwritten.", "example": "A recovery tool pulls tax returns off a \"formatted\" drive bought secondhand."}, {"type": "key_term", "term": "Certificate of destruction", "definition": "Documentation from a disposal vendor, often required for compliance.", "example": "The vendor''s certificate lists every serial number shredded, filed with the audit records."}, {"type": "scenario", "prompt": "A company must destroy data on retired SSDs. Which method will NOT work?", "choices": [{"id": "a", "text": "Shredding"}, {"id": "b", "text": "Secure erase"}, {"id": "c", "text": "Degaussing"}, {"id": "d", "text": "Incineration"}], "answer": "c", "why": "SSDs store data electronically, not magnetically."}, {"type": "scenario", "prompt": "Drives are being reused inside the company and recovery isn''t a concern beyond normal tools. What''s sufficient?", "choices": [{"id": "a", "text": "Shredding"}, {"id": "b", "text": "A secure wipe"}, {"id": "c", "text": "Incineration"}, {"id": "d", "text": "A quick format"}], "answer": "b", "why": "A secure wipe overwrites the data and leaves the drive usable.", "trap": "A quick format leaves data recoverable."}, {"type": "callout", "variant": "tip", "text": "Degaussing does nothing to SSDs. Formatting isn''t erasing."}]'::jsonb where id = '12246ff1-7cbb-4d1e-8730-10a3a93ca8c6';

-- Securing SOHO Wireless and Wired Networks
update lessons set content_blocks = '[{"text": "Securing SOHO Wireless and Wired Networks", "type": "title", "overview": "The concrete hardening checklist for a small office/home office router or access point.", "examContext": "Why this matters: 220-1202 pairs the wireless protocol knowledge from an earlier lesson with the practical SOHO hardening checklist tested here."}, {"type": "diagram", "heading": "SOHO hardening checklist", "diagram": {"kind": "ladder", "rungs": [{"label": "Change default admin credentials", "note": "Highest value, always first."}, {"label": "Update firmware"}, {"label": "Use WPA2 or WPA3 with a strong passphrase"}, {"label": "Disable WPS", "note": "Its PIN can be brute forced."}, {"label": "Disable remote (WAN) administration"}, {"label": "Set up a guest network"}, {"label": "Change or hide the SSID", "note": "Minor benefit."}, {"label": "MAC filtering", "note": "Minor; MAC addresses can be spoofed.", "muted": true}], "top": "most important", "bottom": "least"}}, {"type": "key_term", "term": "Guest network", "definition": "A separate SSID, usually on its own VLAN, keeping visitors away from shares, printers and IoT devices.", "example": "A guest''s infected phone can''t reach the office NAS because it''s on the guest network."}, {"type": "scenario", "prompt": "What''s the single most important step to secure a new SOHO router?", "choices": [{"id": "a", "text": "Hide the SSID"}, {"id": "b", "text": "Change the default admin credentials"}, {"id": "c", "text": "Enable MAC filtering"}, {"id": "d", "text": "Rename the guest network"}], "answer": "b", "why": "Default logins are public knowledge."}, {"type": "scenario", "prompt": "Why disable WPS?", "choices": [{"id": "a", "text": "It slows Wi-Fi"}, {"id": "b", "text": "Its PIN method can be brute forced"}, {"id": "c", "text": "It blocks guests"}, {"id": "d", "text": "It disables WPA3"}], "answer": "b", "why": "The WPS PIN is a known weakness."}, {"type": "callout", "variant": "tip", "text": "Change default credentials first. MAC filtering and hidden SSIDs are minor extras."}]'::jsonb where id = 'd83bf299-b4bc-4f54-ab2f-fc741a27280f';

-- Configuring Browser Security Settings
update lessons set content_blocks = '[{"text": "Configuring Browser Security Settings", "type": "title", "overview": "The browser-level security settings and warning signs a technician configures and explains to end users.", "examContext": "Why this matters: Domain 2 closes with browser security, the layer users interact with most directly, and where many real-world incidents actually begin."}, {"type": "compare", "heading": "Browser security settings", "columns": ["Why it matters"], "rows": [{"label": "Certificate warnings", "values": ["Could mean misconfiguration or an on-path attack; don''t click through on sensitive sites"]}, {"label": "Pop-up blocker", "values": ["Stops scareware and malicious downloads"]}, {"label": "Password manager", "values": ["Unique, strong passwords per site"]}, {"label": "Extension management", "values": ["Extensions can read and change page data"]}, {"label": "Site permissions", "values": ["Camera, microphone, location, notifications"]}]}, {"type": "compare", "heading": "What private browsing does and doesn''t do", "columns": ["Does", "Doesn''t"], "rows": [{"label": "Local device", "values": ["Skips saving history, cookies and form data", "Nothing more"]}, {"label": "Network, ISP, websites", "values": ["Nothing", "Hide your activity from them"]}]}, {"type": "key_term", "term": "Malicious extensions", "definition": "Extensions often request broad permissions and are an overlooked route for malware and data theft.", "example": "A free coupon extension with \"read and change all data on all sites\" is quietly injecting ads and harvesting form data."}, {"type": "scenario", "prompt": "A user thinks incognito mode hides their browsing from their employer''s network. What should the technician explain?", "choices": [{"id": "a", "text": "It does hide it"}, {"id": "b", "text": "It only stops local history and cookies from being saved"}, {"id": "c", "text": "It encrypts all traffic"}, {"id": "d", "text": "It blocks the ISP"}], "answer": "b", "why": "Private browsing affects the local device only."}, {"type": "scenario", "prompt": "A banking site shows a certificate warning. What should the user do?", "choices": [{"id": "a", "text": "Click through; it''s probably fine"}, {"id": "b", "text": "Stop and report it rather than proceeding"}, {"id": "c", "text": "Disable the warning"}, {"id": "d", "text": "Clear the cache"}], "answer": "b", "why": "It could indicate an on-path attack."}, {"type": "callout", "variant": "tip", "text": "Incognito only affects local storage. Don''t click through certificate warnings on sensitive sites."}]'::jsonb where id = '11cdd6bb-acd7-4d28-842c-d095db4a5655';

-- Domain 2 Recap: Security
update lessons set content_blocks = '[{"text": "Domain 2 Recap: Security", "type": "title", "overview": "The highest-yield facts from all 11 Security lessons, gathered in one place before the domain checkpoint.", "examContext": "Why this matters: this recap is ungraded, read it as a final consolidation pass before you attempt the 33-question checkpoint."}, {"type": "term_set", "heading": "Controls and authentication", "terms": [{"term": "Zero trust", "short": "Never trust, always verify."}, {"term": "MFA", "short": "Different categories; two passwords isn''t MFA."}, {"term": "NTFS plus share", "short": "Most restrictive wins."}, {"term": "BitLocker / EFS", "short": "Whole disk / per file."}, {"term": "Personal / Enterprise Wi-Fi", "short": "Shared PSK / per-user 802.1X."}, {"term": "FIDO2 / TOTP / SAML", "short": "Passwordless / rotating codes / single sign-on."}]}, {"type": "term_set", "heading": "Threats", "terms": [{"term": "Worm / virus / Trojan", "short": "Spreads itself / needs help / disguised."}, {"term": "Fileless / cryptominer", "short": "Memory only / high CPU or GPU."}, {"term": "Phishing, vishing, smishing, whaling", "short": "Email, voice, SMS, executives."}, {"term": "Malware removal", "short": "Investigate, quarantine, disable restore, remediate, schedule, re-enable, educate."}]}, {"type": "term_set", "heading": "Hardening and disposal", "terms": [{"term": "EDR / XDR / MDR", "short": "Tool / cross-source / managed team."}, {"term": "Containerization", "short": "Wipe only work data."}, {"term": "Degaussing", "short": "HDDs only, never SSDs."}, {"term": "SOHO first step", "short": "Change default admin credentials."}, {"term": "Incognito", "short": "Local only."}]}, {"type": "scenario", "prompt": "What''s the second step in malware removal?", "choices": [{"id": "a", "text": "Disable System Restore"}, {"id": "b", "text": "Quarantine"}, {"id": "c", "text": "Remediate"}, {"id": "d", "text": "Educate"}], "answer": "b", "why": "Isolate right after verifying."}, {"type": "scenario", "prompt": "Which destruction method fails on SSDs?", "choices": [{"id": "a", "text": "Shredding"}, {"id": "b", "text": "Degaussing"}, {"id": "c", "text": "Incineration"}, {"id": "d", "text": "Secure erase"}], "answer": "b", "why": "SSDs aren''t magnetic."}, {"type": "scenario", "prompt": "Share is Read, NTFS is Modify. Network access?", "choices": [{"id": "a", "text": "Modify"}, {"id": "b", "text": "Read"}, {"id": "c", "text": "Full Control"}, {"id": "d", "text": "None"}], "answer": "b", "why": "Most restrictive."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '70b18ff7-f72b-471d-8e9a-520bf5727a51';

-- Troubleshooting Windows OS Issues Part 1 (Boot and Startup)
update lessons set content_blocks = '[{"text": "Troubleshooting Windows OS Issues Part 1 (Boot and Startup)", "type": "title", "overview": "How to diagnose and fix a Windows PC that won''t boot correctly: BSODs, boot loops, and the built-in recovery environment tools.", "examContext": "Why this matters: boot failures are high-stakes, time-pressured scenarios the exam tests heavily with ''what''s the FIRST step'' framing."}, {"type": "compare", "heading": "Boot symptoms", "columns": ["Likely cause"], "rows": [{"label": "Blue screen (BSOD)", "values": ["Critical fault; the stop code points to the cause"]}, {"label": "Boot loop", "values": ["Corrupted update or driver"]}, {"label": "\"Operating system not found\"", "values": ["Boot order, disk connection or boot sector damage"]}, {"label": "Black screen with only a cursor", "values": ["Graphics driver, Explorer or corrupted profile"]}, {"label": "Slow or failed boot after an update", "values": ["Bad update or incompatible driver"]}]}, {"type": "key_term", "term": "Windows Recovery Environment (WinRE)", "definition": "Reached by repeated failed boots, a recovery drive or Shift+Restart. Offers Startup Repair, System Restore, image recovery, Command Prompt and Startup Settings.", "example": "After three failed boots, WinRE opens; Startup Repair rebuilds damaged boot configuration data."}, {"type": "term_set", "heading": "Recovery tools", "terms": [{"term": "Safe Mode", "short": "Only essential drivers and services; remove a bad driver or malware."}, {"term": "Startup Repair", "short": "Fixes common boot problems automatically."}, {"term": "Uninstall an update", "short": "wusa /uninstall /kb:number from Safe Mode or WinRE."}]}, {"type": "scenario", "prompt": "A PC started blue screening at boot right after last night''s driver update. What''s the fastest likely fix?", "choices": [{"id": "a", "text": "Reinstall Windows"}, {"id": "b", "text": "Boot to Safe Mode or WinRE and roll back that driver"}, {"id": "c", "text": "Replace the hard drive"}, {"id": "d", "text": "Run chkdsk"}], "answer": "b", "why": "Undo the specific change that caused it."}, {"type": "scenario", "prompt": "A PC reports \"Operating system not found\" after a USB stick was left plugged in. What should be checked?", "choices": [{"id": "a", "text": "The graphics driver"}, {"id": "b", "text": "Boot order in firmware"}, {"id": "c", "text": "User profile"}, {"id": "d", "text": "Windows Update"}], "answer": "b", "why": "It may be trying to boot from the USB stick."}, {"type": "callout", "variant": "tip", "text": "Broke right after an update or driver? Remove that change in Safe Mode or WinRE before considering a reinstall."}]'::jsonb where id = '5c8e3735-f680-4389-89d3-0fe549a0fc26';

-- Troubleshooting Windows OS Issues Part 2 (Performance and Resources)
update lessons set content_blocks = '[{"text": "Troubleshooting Windows OS Issues Part 2 (Performance and Resources)", "type": "title", "overview": "How to diagnose a slow-running Windows system using Task Manager and Resource Monitor, and common causes of degraded performance.", "examContext": "Why this matters: performance complaints are among the most common real-world tickets, and the exam expects a systematic diagnostic approach."}, {"type": "compare", "heading": "Performance symptoms", "columns": ["Check"], "rows": [{"label": "High CPU", "values": ["Task Manager sorted by CPU: runaway process, malware, cryptominer"]}, {"label": "100% disk", "values": ["Search indexing, SysMain, failing or nearly full drive"]}, {"label": "Memory leak", "values": ["A process''s memory climbs steadily; restart it"]}, {"label": "Slow startup", "values": ["Too many startup apps; Task Manager Startup tab"]}, {"label": "Low free space", "values": ["Below roughly 10 to 15% free, performance suffers"]}]}, {"type": "key_term", "term": "Page file", "definition": "Disk space used as overflow for RAM. Heavy use is a sign the PC needs more memory.", "example": "Resource Monitor shows constant hard faults while 8 GB of RAM is full; upgrading to 16 GB fixes the sluggishness."}, {"type": "key_term", "term": "Resource Monitor", "definition": "More detail than Task Manager: per-process disk, network and memory activity.", "example": "Task Manager shows 100% disk; Resource Monitor reveals the search indexer reading thousands of files."}, {"type": "scenario", "prompt": "Disk usage sits at 100% with no single obvious process. What should be checked before suspecting malware?", "choices": [{"id": "a", "text": "The monitor cable"}, {"id": "b", "text": "Windows Search indexing and drive health or free space"}, {"id": "c", "text": "The DNS server"}, {"id": "d", "text": "BitLocker"}], "answer": "b", "why": "These are the common benign causes."}, {"type": "scenario", "prompt": "An app''s memory use rises from 300 MB to 6 GB over a day and drops when restarted. What is this?", "choices": [{"id": "a", "text": "Page file"}, {"id": "b", "text": "Memory leak"}, {"id": "c", "text": "Thermal throttling"}, {"id": "d", "text": "Fileless malware"}], "answer": "b", "why": "Steady growth without release is a leak."}, {"type": "callout", "variant": "tip", "text": "100% disk with no culprit: indexing or the drive itself. Heavy page file use: add RAM."}]'::jsonb where id = 'a40b3270-2b32-4ae2-92ef-5d3bb2e9e54e';

-- Troubleshooting Windows OS Issues Part 3 (Applications, Updates, and File System)
update lessons set content_blocks = '[{"text": "Troubleshooting Windows OS Issues Part 3 (Applications, Updates, and File System)", "type": "title", "overview": "Diagnosing application-level crashes, stuck or failed Windows Updates, and underlying file system corruption.", "examContext": "Why this matters: this lesson rounds out Windows troubleshooting with the application- and file-level issues that complement the boot and performance problems from the prior two lessons."}, {"type": "compare", "heading": "Symptom to fix", "columns": ["Fix"], "rows": [{"label": "App won''t launch", "values": ["Install missing dependencies, repair the app, or run as administrator"]}, {"label": "App hangs", "values": ["End it in Task Manager; check for updates or compatibility issues"]}, {"label": "Windows Update stuck", "values": ["Update troubleshooter, or clear the SoftwareDistribution folder"]}, {"label": "Files won''t open", "values": ["chkdsk for disk errors; sfc if system files are suspected"]}, {"label": "Legacy app fails", "values": ["Compatibility Mode in the .exe''s Properties"]}]}, {"type": "diagram", "heading": "When sfc can''t fix everything", "diagram": {"kind": "flow", "steps": [{"label": "sfc /scannow", "note": "Reports some files couldn''t be fixed."}, {"label": "DISM /Online /Cleanup-Image /RestoreHealth", "note": "Repairs the component store sfc copies from."}, {"label": "sfc /scannow again", "note": "Now it can repair."}, {"label": "Repair install", "note": "If it still fails; keeps files and most apps."}]}}, {"type": "scenario", "prompt": "sfc /scannow reports it couldn''t repair some files. What''s next?", "choices": [{"id": "a", "text": "Reinstall Windows"}, {"id": "b", "text": "Run DISM /RestoreHealth, then sfc again"}, {"id": "c", "text": "Run chkdsk /f"}, {"id": "d", "text": "Disable Windows Update"}], "answer": "b", "why": "DISM fixes the source sfc relies on."}, {"type": "scenario", "prompt": "An accounting program from 2012 won''t start on Windows 11. What should be tried?", "choices": [{"id": "a", "text": "Compatibility Mode"}, {"id": "b", "text": "DISM"}, {"id": "c", "text": "Safe Mode"}, {"id": "d", "text": "Disk cleanup"}], "answer": "a", "why": "It runs the app as if on an older Windows version."}, {"type": "callout", "variant": "tip", "text": "sfc fails? DISM, then sfc again. Old app? Compatibility Mode."}]'::jsonb where id = 'a6e0bebb-9ed1-4899-88a0-dea337d4cb7b';

-- Troubleshooting Mobile OS Issues
update lessons set content_blocks = '[{"text": "Troubleshooting Mobile OS Issues", "type": "title", "overview": "Common mobile device (phone/tablet) OS-level symptoms and their typical causes and fixes.", "examContext": "Why this matters: 220-1202''s Software Troubleshooting domain shifts from Windows to mobile OS issues, testing a distinct set of symptoms and tools."}, {"type": "compare", "heading": "Mobile OS symptoms", "columns": ["Likely cause"], "rows": [{"label": "Rapid battery drain", "values": ["Background app, brightness, failing battery"]}, {"label": "Overheating", "values": ["Heavy use, sunlight, failing battery, malware"]}, {"label": "Unresponsive touchscreen", "values": ["Frozen OS, cracked digitizer, screen protector"]}, {"label": "No signal", "values": ["Airplane mode, SIM seating, carrier outage, network settings"]}, {"label": "Random reboots", "values": ["Failing battery, heat protection, bad update"]}]}, {"type": "diagram", "heading": "Escalating fixes", "diagram": {"kind": "flow", "steps": [{"label": "Force restart", "note": "Button combination that bypasses a frozen OS."}, {"label": "Check for OS updates"}, {"label": "Reset network settings", "note": "Clears Wi-Fi, APN and Bluetooth settings."}, {"label": "Factory reset", "note": "Last resort, after backing up."}]}}, {"type": "key_term", "term": "Battery usage by app", "definition": "The fastest way to find what''s draining the battery.", "example": "Settings shows a navigation app using 45% of the battery in the background; restricting it fixes the drain."}, {"type": "scenario", "prompt": "A phone''s screen won''t respond to touch. What''s the first step?", "choices": [{"id": "a", "text": "Factory reset"}, {"id": "b", "text": "Force restart"}, {"id": "c", "text": "Replace the screen"}, {"id": "d", "text": "Reset network settings"}], "answer": "b", "why": "Start with the least destructive fix."}, {"type": "scenario", "prompt": "A phone has signal bars but can''t use mobile data after a carrier change. Wi-Fi works fine. What might help?", "choices": [{"id": "a", "text": "Factory reset"}, {"id": "b", "text": "Reset network settings"}, {"id": "c", "text": "Replace the battery"}, {"id": "d", "text": "Clear the app cache"}], "answer": "b", "why": "Corrupted network or APN settings are a common cause."}, {"type": "callout", "variant": "tip", "text": "Force restart first, factory reset last."}]'::jsonb where id = 'fbff70af-3b40-4aa5-b305-4c2baece0498';

-- Troubleshooting Mobile Application Issues
update lessons set content_blocks = '[{"text": "Troubleshooting Mobile Application Issues", "type": "title", "overview": "Diagnosing individual app problems on a mobile device, distinct from OS-wide issues covered in the previous lesson.", "examContext": "Why this matters: the exam distinguishes OS-level mobile problems from app-level ones, knowing which layer a symptom belongs to determines the right fix."}, {"type": "compare", "heading": "App symptoms", "columns": ["Try"], "rows": [{"label": "Crashes repeatedly", "values": ["Update, clear cache or data, reinstall"]}, {"label": "Won''t install", "values": ["Free storage; check the required OS version"]}, {"label": "Won''t sync", "values": ["Network, correct account, background refresh"]}, {"label": "Slow", "values": ["Clear cache, update, close background apps"]}, {"label": "Asks for odd permissions", "values": ["Treat as a red flag"]}]}, {"type": "compare", "heading": "Cache vs. data", "columns": ["Cache", "Data (storage)"], "rows": [{"label": "Holds", "values": ["Temporary files and images", "Logins, settings, user content"]}, {"label": "Clearing it", "values": ["Safe; often fixes glitches", "Resets the app like a fresh install"]}]}, {"type": "diagram", "heading": "Least destructive first", "diagram": {"kind": "flow", "steps": [{"label": "Clear cache"}, {"label": "Update the app"}, {"label": "Clear app data"}, {"label": "Reinstall"}]}}, {"type": "scenario", "prompt": "A messaging app only shows new messages when it''s opened. What''s a likely cause?", "choices": [{"id": "a", "text": "Corrupted OS"}, {"id": "b", "text": "Background app refresh is off for that app"}, {"id": "c", "text": "Low storage"}, {"id": "d", "text": "Bad SIM"}], "answer": "b", "why": "The app can''t fetch in the background."}, {"type": "scenario", "prompt": "An app crashes on launch. What should be tried first?", "choices": [{"id": "a", "text": "Factory reset"}, {"id": "b", "text": "Clear the app''s cache"}, {"id": "c", "text": "Clear the app''s data"}, {"id": "d", "text": "Reinstall the OS"}], "answer": "b", "why": "The least destructive step."}, {"type": "callout", "variant": "tip", "text": "Cache, update, data, reinstall. If only one app misbehaves, the problem is the app."}]'::jsonb where id = '6cf94752-46c0-44fb-a391-0756c8fc76d9';

-- Troubleshooting Mobile OS Security Issues
update lessons set content_blocks = '[{"text": "Troubleshooting Mobile OS Security Issues", "type": "title", "overview": "The symptoms of a mobile device compromise at the OS level, and the response steps once one is suspected.", "examContext": "Why this matters: mobile OS security issues are a distinct scenario category from general mobile OS troubleshooting, the exam expects recognition of compromise-specific symptoms."}, {"type": "compare", "heading": "Signs of a compromised device", "columns": ["What it suggests"], "rows": [{"label": "Data usage spike", "values": ["Malware sending data in the background"]}, {"label": "Unknown sign-in alerts", "values": ["Stolen credentials"]}, {"label": "Ads and pop-ups outside the browser", "values": ["Adware from a sideloaded or shady app"]}, {"label": "Battery drain with data use", "values": ["Malware actively running"]}, {"label": "Apps the user didn''t install", "values": ["Further payloads, or a jailbroken or rooted device"]}, {"label": "Odd tracking behavior", "values": ["Stalkerware"]}]}, {"type": "key_term", "term": "Jailbreaking and rooting", "definition": "Removing iOS or Android restrictions for full access. Bypasses built-in protections, raises malware risk and usually voids the warranty.", "example": "A rooted phone installs a \"free\" app from a forum that quietly reads every SMS."}, {"type": "diagram", "heading": "Responding to a compromised phone", "diagram": {"kind": "flow", "steps": [{"label": "Isolate", "note": "Airplane mode or turn off data."}, {"label": "Change passwords", "note": "From a known-clean device."}, {"label": "Scan", "note": "Reputable mobile security tool."}, {"label": "Remove suspicious apps"}, {"label": "Factory reset", "note": "If doubt remains; back up only clean data."}]}}, {"type": "scenario", "prompt": "A user''s phone started showing full-screen ads on the home screen after they rooted it and installed apps from a website. What''s the root enabler?", "choices": [{"id": "a", "text": "A bad battery"}, {"id": "b", "text": "Rooting removed built-in protections"}, {"id": "c", "text": "The carrier"}, {"id": "d", "text": "Low storage"}], "answer": "b", "why": "Rooting weakens the security model."}, {"type": "scenario", "prompt": "A phone shows a huge data spike overnight while unused. What should the user do first?", "choices": [{"id": "a", "text": "Factory reset immediately"}, {"id": "b", "text": "Isolate it by turning off data or using airplane mode"}, {"id": "c", "text": "Ignore it"}, {"id": "d", "text": "Clear the browser cache"}], "answer": "b", "why": "Contain first."}, {"type": "callout", "variant": "tip", "text": "Jailbroken or rooted before the symptoms? That''s the likely enabler. Isolate before anything else."}]'::jsonb where id = '1010d548-09bf-4b5e-84cb-66e5abf09a25';

-- Troubleshooting Mobile Application Security Issues
update lessons set content_blocks = '[{"text": "Troubleshooting Mobile Application Security Issues", "type": "title", "overview": "Recognizing and responding to app-level security problems specifically, as distinct from device-wide OS compromise.", "examContext": "Why this matters: this lesson narrows the focus from Domain 3''s mobile OS security lesson down to the specific app-level red flags and responses the exam tests."}, {"type": "term_set", "heading": "App-level red flags", "terms": [{"term": "Fake or cloned apps", "short": "Lookalike name and icon to steal credentials or install malware."}, {"term": "Excessive permissions", "short": "A flashlight app wanting contacts and SMS."}, {"term": "Malvertising", "short": "Malicious ads served inside an otherwise normal app."}, {"term": "Data leakage", "short": "Data sent unencrypted or credentials stored insecurely."}, {"term": "In-app scareware", "short": "\"Your device is infected, tap to fix.\""}]}, {"type": "key_term", "term": "Malvertising", "definition": "Malicious ads delivered through an ad network, often in a legitimate app, that redirect to phishing or trigger downloads.", "example": "A puzzle game''s banner ad redirects to a fake app store page asking for an Apple ID."}, {"type": "term_set", "heading": "Before installing, check", "terms": [{"term": "Developer reputation", "short": "Is this the real publisher?"}, {"term": "Reviews", "short": "Watch for generic, suspicious five-star reviews."}, {"term": "Downloads and last update", "short": "Abandoned apps are riskier."}]}, {"type": "scenario", "prompt": "A game shows a pop-up saying the phone is infected and to tap to install a cleaner. What is it?", "choices": [{"id": "a", "text": "A real OS alert"}, {"id": "b", "text": "Scareware"}, {"id": "c", "text": "MDM policy"}, {"id": "d", "text": "A carrier message"}], "answer": "b", "why": "Real security tools don''t work this way."}, {"type": "scenario", "prompt": "A confirmed malicious app is found. What''s the response?", "choices": [{"id": "a", "text": "Leave it but deny permissions"}, {"id": "b", "text": "Uninstall it, scan, and change passwords entered into it"}, {"id": "c", "text": "Factory reset immediately"}, {"id": "d", "text": "Update it"}], "answer": "b", "why": "Remove it, look for anything it dropped, and rotate exposed credentials."}, {"type": "callout", "variant": "tip", "text": "Permissions far beyond the app''s purpose are a red flag. In-app \"you''re infected\" pop-ups are fake."}]'::jsonb where id = '93da07c9-34f7-4cfe-bee3-5c66550cf2c5';

-- Troubleshooting PC Security Issues Part 1 (Malware and Unwanted Software)
update lessons set content_blocks = '[{"text": "Troubleshooting PC Security Issues Part 1 (Malware and Unwanted Software)", "type": "title", "overview": "The observable symptoms that point to a Windows PC being infected with malware or bundled unwanted software (PUPs).", "examContext": "Why this matters: this lesson provides the symptom-recognition skill that feeds directly into the SOHO malware removal process covered in Domain 2."}, {"type": "compare", "heading": "Infection symptoms", "columns": ["Suggests"], "rows": [{"label": "Pop-ups and browser redirects", "values": ["Adware or a browser hijacker"]}, {"label": "Antivirus or firewall turned off", "values": ["Malware hiding itself; a strong indicator"]}, {"label": "Renamed or missing files", "values": ["Ransomware or a destructive payload"]}, {"label": "Unusual outbound connections", "values": ["Command and control traffic"]}, {"label": "New toolbars or extensions", "values": ["A bundled PUP"]}, {"label": "High unexplained resource use", "values": ["Cryptominer or other malware"]}]}, {"type": "key_term", "term": "Potentially unwanted program (PUP)", "definition": "Not strictly malicious but unwanted, usually bundled with free software through a missed opt-out checkbox.", "example": "A free PDF converter also installed a search toolbar and a \"PC optimizer\" that nags constantly."}, {"type": "key_term", "term": "Spotting command and control", "definition": "netstat or Resource Monitor''s network tab shows connections to unfamiliar external addresses.", "example": "notepad.exe holding an open connection to an overseas IP is a clear sign something is wrong."}, {"type": "scenario", "prompt": "A user says their antivirus \"turned itself off\" and won''t turn back on. How should this be treated?", "choices": [{"id": "a", "text": "A settings glitch"}, {"id": "b", "text": "A strong sign of active malware"}, {"id": "c", "text": "Normal after updates"}, {"id": "d", "text": "A licensing issue"}], "answer": "b", "why": "Malware commonly disables security tools first."}, {"type": "scenario", "prompt": "After installing a free video tool, a new search toolbar appeared and the homepage changed. What was installed?", "choices": [{"id": "a", "text": "Ransomware"}, {"id": "b", "text": "A PUP"}, {"id": "c", "text": "A rootkit"}, {"id": "d", "text": "A worm"}], "answer": "b", "why": "Bundled unwanted software."}, {"type": "callout", "variant": "tip", "text": "Security software disabling itself is never just a glitch. Check netstat for strange connections."}]'::jsonb where id = '16bfecaa-f1bc-4aab-a339-c678411a0d93';

-- Troubleshooting PC Security Issues Part 2 (Unauthorized Access, Browser, and Network)
update lessons set content_blocks = '[{"text": "Troubleshooting PC Security Issues Part 2 (Unauthorized Access, Browser, and Network)", "type": "title", "overview": "Rounding out PC security troubleshooting with unauthorized access symptoms, browser-level compromise, and local network-level red flags.", "examContext": "Why this matters: this lesson closes Domain 3 by extending symptom recognition from the local PC out to account and network-level compromise indicators."}, {"type": "compare", "heading": "Unauthorized access symptoms", "columns": ["Suggests"], "rows": [{"label": "Unexpected account lockouts", "values": ["Someone guessing passwords"]}, {"label": "Unfamiliar sign-ins", "values": ["Stolen credentials; check sign-in history"]}, {"label": "New local accounts nobody created", "values": ["A backdoor from an attacker with admin access"]}, {"label": "Unexplained setting changes", "values": ["Firewall rules, startup items or permissions altered"]}]}, {"type": "key_term", "term": "Browser hijacking", "definition": "Unauthorized changes to homepage, search engine, new tab page or extensions, usually by adware or a PUP.", "example": "Every search now goes through an unfamiliar search site stuffed with ads."}, {"type": "key_term", "term": "Compromised router", "definition": "If several devices show problems at once, look at the router: unknown devices, changed DNS, odd outbound traffic.", "example": "Three family laptops all land on fake banking pages; the router''s DNS was changed to an attacker''s server."}, {"type": "scenario", "prompt": "Every device on a home network is suddenly redirected to fake login pages. Where should the investigation focus?", "choices": [{"id": "a", "text": "Each PC''s browser"}, {"id": "b", "text": "The router, especially its DNS settings"}, {"id": "c", "text": "The printer"}, {"id": "d", "text": "The ISP''s billing"}], "answer": "b", "why": "Simultaneous symptoms across devices point to shared infrastructure."}, {"type": "scenario", "prompt": "A technician finds a local admin account called \"support2\" that nobody created. What does it suggest?", "choices": [{"id": "a", "text": "A Windows update"}, {"id": "b", "text": "An attacker''s backdoor account"}, {"id": "c", "text": "A PUP"}, {"id": "d", "text": "A normal service account"}], "answer": "b", "why": "Unknown admin accounts indicate persistence."}, {"type": "callout", "variant": "tip", "text": "Many devices affected at once: check the router. Unknown admin accounts are backdoors."}]'::jsonb where id = '2cc3b71d-94b3-4494-9ff0-5d834ecb4cb2';

-- Domain 3 Recap: Software Troubleshooting
update lessons set content_blocks = '[{"text": "Domain 3 Recap: Software Troubleshooting", "type": "title", "overview": "The highest-yield facts from all 9 Software Troubleshooting lessons, gathered in one place before the domain checkpoint.", "examContext": "Why this matters: this recap is ungraded, read it as a final consolidation pass before you attempt the 27-question checkpoint."}, {"type": "term_set", "heading": "Windows", "terms": [{"term": "WinRE", "short": "Startup Repair, System Restore, Command Prompt, Safe Mode."}, {"term": "Broke after an update", "short": "Uninstall it."}, {"term": "100% disk", "short": "Indexing, drive health or free space."}, {"term": "Memory leak / page file", "short": "Climbing usage / not enough RAM."}, {"term": "sfc fails", "short": "DISM, then sfc again."}]}, {"type": "term_set", "heading": "Mobile", "terms": [{"term": "Order", "short": "Force restart, update, reset network settings, factory reset."}, {"term": "App fixes", "short": "Cache, update, data, reinstall."}, {"term": "Jailbreak or root", "short": "Removes protections."}, {"term": "In-app infected warning", "short": "Scareware."}]}, {"type": "term_set", "heading": "PC security", "terms": [{"term": "AV disabled itself", "short": "Strong malware sign."}, {"term": "PUP", "short": "Bundled unwanted software."}, {"term": "Browser hijacking", "short": "Changed homepage and search."}, {"term": "Many devices affected", "short": "Check the router."}]}, {"type": "scenario", "prompt": "A phone is frozen. First step?", "choices": [{"id": "a", "text": "Factory reset"}, {"id": "b", "text": "Force restart"}, {"id": "c", "text": "Reset network settings"}, {"id": "d", "text": "Reinstall apps"}], "answer": "b", "why": "Least destructive first."}, {"type": "scenario", "prompt": "What runs after sfc reports it couldn''t fix files?", "choices": [{"id": "a", "text": "chkdsk"}, {"id": "b", "text": "DISM /RestoreHealth"}, {"id": "c", "text": "diskpart"}, {"id": "d", "text": "gpupdate"}], "answer": "b", "why": "Repair the component store."}, {"type": "scenario", "prompt": "Antivirus won''t turn back on. Most likely?", "choices": [{"id": "a", "text": "Glitch"}, {"id": "b", "text": "Malware"}, {"id": "c", "text": "Update"}, {"id": "d", "text": "License"}], "answer": "b", "why": "Malware disables defenses."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '825125de-8ab0-431a-9b92-3b1eb4320704';

-- Documentation, Ticketing, and Change Management Procedures
update lessons set content_blocks = '[{"text": "Documentation, Ticketing, and Change Management Procedures", "type": "title", "overview": "How IT support tracks work through a ticketing system and documentation, and the formal process for making changes to production systems safely.", "examContext": "Why this matters: Domain 4 opens with the administrative backbone of IT support work, the exam tests both ticketing fields and the specific steps of formal change management."}, {"type": "term_set", "heading": "What a good ticket holds", "terms": [{"term": "User information", "short": "Contact, department, asset tag."}, {"term": "Description and category", "short": "What''s wrong, and whether it''s hardware, software or network."}, {"term": "Severity or priority", "short": "Drives response time targets."}, {"term": "Progress notes", "short": "Every step tried and its result."}, {"term": "Resolution and root cause", "short": "What fixed it and why; feeds the knowledge base."}]}, {"type": "diagram", "heading": "Change management", "diagram": {"kind": "flow", "steps": [{"label": "Change request", "note": "What, why and how."}, {"label": "Risk analysis"}, {"label": "Rollback plan", "note": "How to undo it."}, {"label": "Approval"}, {"label": "Notify users"}, {"label": "Implement in the maintenance window"}]}}, {"type": "term_set", "heading": "Supporting documentation", "terms": [{"term": "Asset management", "short": "Purchase date, warranty, user and location of every device."}, {"term": "Knowledge base", "short": "Documented fixes for repeat issues; can power self-service."}, {"term": "SOP", "short": "The approved, repeatable way to do a task."}]}, {"type": "scenario", "prompt": "A technician wants to push an urgent firewall change during lunch with no rollback plan, because \"it''s small.\" What''s wrong?", "choices": [{"id": "a", "text": "Nothing; it''s small"}, {"id": "b", "text": "It skips the rollback plan and approval that change management requires"}, {"id": "c", "text": "It should be done at night only"}, {"id": "d", "text": "Users never need notice"}], "answer": "b", "why": "Change management doesn''t skip rollback or approval, even under pressure."}, {"type": "scenario", "prompt": "Where should a fix for a recurring printer error be recorded so others can resolve it quickly next time?", "choices": [{"id": "a", "text": "Asset inventory"}, {"id": "b", "text": "Knowledge base"}, {"id": "c", "text": "Change request"}, {"id": "d", "text": "Risk register"}], "answer": "b", "why": "That''s the knowledge base''s job."}, {"type": "callout", "variant": "tip", "text": "Change management never skips the rollback plan or approval."}]'::jsonb where id = 'b710b00a-5238-4416-b90b-9d0d61df5af9';

-- Workstation Backup and Recovery Methods
update lessons set content_blocks = '[{"text": "Workstation Backup and Recovery Methods", "type": "title", "overview": "Backup types and their tradeoffs, the 3-2-1 backup rule, and why testing a backup''s restorability matters as much as taking the backup itself.", "examContext": "Why this matters: backup type tradeoffs (speed vs. restore complexity) are one of the most reliably tested comparison questions on this domain."}, {"type": "compare", "heading": "Backup types", "columns": ["Full", "Incremental", "Differential"], "rows": [{"label": "Copies", "values": ["Everything", "Changes since the last backup of any kind", "Changes since the last full"]}, {"label": "Backup speed", "values": ["Slowest", "Fastest", "Middle"]}, {"label": "Restore needs", "values": ["Just the full", "Full plus every incremental", "Full plus the latest differential"]}, {"label": "Restore speed", "values": ["Fastest", "Slowest", "Middle"]}], "intro": "A **synthetic full** combines a full and later incrementals into a new full without rereading the source."}, {"type": "diagram", "heading": "The 3-2-1 rule", "diagram": {"kind": "triad", "points": [{"label": "3 copies", "note": "Of your data."}, {"label": "2 media types", "note": "Such as disk and cloud."}, {"label": "1 off-site", "note": "Survives fire, flood or ransomware on site."}], "center": "3-2-1"}}, {"type": "key_term", "term": "Test restores", "definition": "A backup is only as good as a proven restore. Test periodically.", "example": "A quarterly test finds the backup job has silently skipped the finance share for two months."}, {"type": "key_term", "term": "Grandfather-father-son (GFS)", "definition": "A rotation keeping daily (son), weekly (father) and monthly (grandfather) sets.", "example": "A user can recover a file as it was yesterday, three weeks ago or five months ago."}, {"type": "scenario", "prompt": "Which backup type is fastest to restore?", "choices": [{"id": "a", "text": "Incremental"}, {"id": "b", "text": "Differential"}, {"id": "c", "text": "Full"}, {"id": "d", "text": "Synthetic incremental"}], "answer": "c", "why": "One set holds everything."}, {"type": "scenario", "prompt": "Ransomware encrypted the office server and the USB backup drive plugged into it. Which rule would have protected them?", "choices": [{"id": "a", "text": "GFS"}, {"id": "b", "text": "3-2-1 with an off-site copy"}, {"id": "c", "text": "Differential backups"}, {"id": "d", "text": "Full backups only"}], "answer": "b", "why": "An off-site copy survives on-site damage."}, {"type": "callout", "variant": "tip", "text": "Full: slowest to make, fastest to restore. Incremental: the reverse. 3-2-1 with one off-site."}]'::jsonb where id = '89fe9cfa-c231-4c36-9797-2e946944e84c';

-- Safety Procedures and Environmental Impacts
update lessons set content_blocks = '[{"text": "Safety Procedures and Environmental Impacts", "type": "title", "overview": "Personal and equipment safety practices, plus environmental factors (temperature, humidity, ventilation) that affect equipment reliability.", "examContext": "Why this matters: safety and environmental questions are usually straightforward, but the exam expects precise terminology (ESD, MSDS/SDS) and correct disposal procedures."}, {"type": "term_set", "heading": "Personal and equipment safety", "terms": [{"term": "ESD prevention", "short": "Wrist strap, anti-static mat, grounding."}, {"term": "Lifting", "short": "With the legs, not the back."}, {"term": "Electrical", "short": "Unplug first; never open a PSU or CRT, which hold dangerous charge."}, {"term": "Cable management", "short": "Prevents trips and keeps airflow clear."}, {"term": "Fire", "short": "Class C extinguisher for electrical fires, never water."}]}, {"type": "key_term", "term": "Safety Data Sheet (SDS)", "definition": "Formerly MSDS. Describes a hazardous material''s properties, safe handling, storage and emergency response.", "example": "A technician checks the toner''s SDS before cleaning up a large spill."}, {"type": "compare", "heading": "Environmental controls", "columns": ["Too much", "Too little"], "rows": [{"label": "Humidity", "values": ["Corrosion and shorts", "Static buildup"]}, {"label": "Temperature", "values": ["Overheating and failures", "Condensation when warming"]}], "intro": "Add good **airflow**, a **UPS** for surges and short outages, and **regulated e-waste disposal** for batteries, monitors and toner."}, {"type": "scenario", "prompt": "A power strip under a desk catches fire. Which extinguisher?", "choices": [{"id": "a", "text": "Water"}, {"id": "b", "text": "Class A"}, {"id": "c", "text": "Class C"}, {"id": "d", "text": "Foam"}], "answer": "c", "why": "Class C is for electrical fires; water is a shock hazard."}, {"type": "scenario", "prompt": "Where would a technician find safe handling instructions for a cleaning solvent?", "choices": [{"id": "a", "text": "The EULA"}, {"id": "b", "text": "The SDS"}, {"id": "c", "text": "The knowledge base"}, {"id": "d", "text": "The asset register"}], "answer": "b", "why": "The safety data sheet."}, {"type": "callout", "variant": "tip", "text": "Electrical fire: Class C. Hazardous material: SDS. Never open a power supply."}]'::jsonb where id = 'cf4d0458-5e6c-4acb-a898-5b490835acff';

-- Prohibited Content, Privacy, Licensing, and Policy Concepts
update lessons set content_blocks = '[{"text": "Prohibited Content, Privacy, Licensing, and Policy Concepts", "type": "title", "overview": "How to properly respond to and document a discovery of prohibited content, software licensing distinctions, and regulated data categories technicians must recognize.", "examContext": "Why this matters: discovering prohibited content is a rare but high-stakes scenario the exam tests precisely, mishandling evidence or process can have serious legal consequences."}, {"type": "diagram", "heading": "Discovering prohibited content", "diagram": {"kind": "flow", "steps": [{"label": "Report it immediately", "note": "Supervisor or compliance contact. Don''t investigate, copy or forward."}, {"label": "Preserve the evidence", "note": "Don''t power off, delete or browse further."}, {"label": "Maintain chain of custody", "note": "Record everyone who handles it."}, {"label": "Follow the incident policy"}]}}, {"type": "key_term", "term": "Chain of custody", "definition": "An unbroken record of who handled evidence, when and what they did. A gap can make it unusable.", "example": "The laptop is bagged, tagged and signed over from the technician to the security manager with times recorded."}, {"type": "compare", "heading": "Licensing models", "columns": ["Covers"], "rows": [{"label": "Per device", "values": ["One installation"]}, {"label": "Per user", "values": ["One person, on several devices"]}, {"label": "Volume or site", "values": ["Many installations under one agreement"]}, {"label": "Open source (such as GPL)", "values": ["Source freely available; terms vary"]}, {"label": "EULA", "values": ["The legal terms accepted at install"]}]}, {"type": "compare", "heading": "Regulated data", "columns": ["What it is", "Governed by"], "rows": [{"label": "PII", "values": ["Name, Social Security number, address", "Privacy laws and policy"]}, {"label": "PHI", "values": ["Health information", "HIPAA"]}, {"label": "PCI data", "values": ["Payment card data", "PCI DSS"]}]}, {"type": "scenario", "prompt": "While repairing a laptop, a technician sees what appears to be illegal content. What should they do first?", "choices": [{"id": "a", "text": "Delete it"}, {"id": "b", "text": "Report it through the proper channel and preserve the device"}, {"id": "c", "text": "Copy it as evidence"}, {"id": "d", "text": "Ask the owner about it"}], "answer": "b", "why": "Report and preserve; never investigate, delete or forward."}, {"type": "scenario", "prompt": "A patient''s diagnosis and treatment records are what kind of data?", "choices": [{"id": "a", "text": "PCI"}, {"id": "b", "text": "PHI"}, {"id": "c", "text": "Open source"}, {"id": "d", "text": "EULA"}], "answer": "b", "why": "Protected health information under HIPAA."}, {"type": "callout", "variant": "tip", "text": "Found something illegal: report through official channels and preserve it. Nothing else."}]'::jsonb where id = '0d91bdc7-7e44-4569-99e3-090097c1b3d3';

-- Communication Techniques and Professionalism
update lessons set content_blocks = '[{"text": "Communication Techniques and Professionalism", "type": "title", "overview": "The soft-skills side of IT support: how to communicate clearly and behave professionally with end users, especially in stressful situations.", "examContext": "Why this matters: professionalism questions are usually intuitive but still scored, the exam expects the textbook ''best practice'' answer, not just common sense."}, {"type": "term_set", "heading": "Communication best practices", "terms": [{"term": "Active listening", "short": "Let the user finish; restate the problem to confirm."}, {"term": "Plain language", "short": "No jargon beyond the user''s level."}, {"term": "Set expectations", "short": "Realistic timeframes; update proactively on delays."}, {"term": "Positive attitude", "short": "Never minimize the problem."}, {"term": "Not judgmental", "short": "Never make the user feel foolish."}]}, {"type": "key_term", "term": "De-escalation", "definition": "Stay calm, don''t argue or get defensive, acknowledge the frustration and steer toward concrete next steps.", "example": "\"I understand losing that report is stressful. Let''s check whether a previous version can be restored right now.\""}, {"type": "term_set", "heading": "On-site professionalism", "terms": [{"term": "Punctuality", "short": "On time, or call ahead if delayed."}, {"term": "Follow-through", "short": "Make promised callbacks."}, {"term": "Respect privacy", "short": "Don''t browse personal files or touch personal items without asking."}]}, {"type": "scenario", "prompt": "A user is shouting that IT \"never fixes anything.\" What''s the best response?", "choices": [{"id": "a", "text": "Explain it''s their fault"}, {"id": "b", "text": "Stay calm, listen and focus on next steps"}, {"id": "c", "text": "Hang up"}, {"id": "d", "text": "Escalate immediately without listening"}], "answer": "b", "why": "Defensiveness or dismissiveness is always the wrong answer."}, {"type": "scenario", "prompt": "A fix will take two hours longer than promised. What should the technician do?", "choices": [{"id": "a", "text": "Say nothing until done"}, {"id": "b", "text": "Tell the user proactively with a new estimate"}, {"id": "c", "text": "Close the ticket"}, {"id": "d", "text": "Hand it to someone else silently"}], "answer": "b", "why": "Manage expectations."}, {"type": "callout", "variant": "tip", "text": "Upset user: stay calm, listen, don''t argue. Communicate delays before they''re noticed."}]'::jsonb where id = '2b54e3f8-f13a-4fca-90c2-834290c62052';

-- Basics of Scripting
update lessons set content_blocks = '[{"text": "Basics of Scripting", "type": "title", "overview": "Recognizing common scripting languages by file extension, basic scripting constructs, and the security considerations around running scripts.", "examContext": "Why this matters: 220-1202 doesn''t expect you to write complex code, but does expect you to recognize script types and basic logic for support/automation purposes."}, {"type": "compare", "heading": "Script file types", "columns": ["Language", "Platform"], "rows": [{"label": ".bat", "values": ["Batch", "Windows"]}, {"label": ".ps1", "values": ["PowerShell", "Windows"]}, {"label": ".vbs", "values": ["VBScript", "Windows, legacy"]}, {"label": ".sh", "values": ["Bash shell", "Linux and macOS"]}, {"label": ".py", "values": ["Python", "Cross-platform"]}, {"label": ".js", "values": ["JavaScript", "Browsers and Node.js"]}]}, {"type": "term_set", "heading": "Universal building blocks", "terms": [{"term": "Variables", "short": "Named storage for a value."}, {"term": "Loops", "short": "Repeat an action, such as for each file."}, {"term": "Conditionals", "short": "If this, do X; otherwise do Y."}, {"term": "Comments", "short": "Notes ignored by the interpreter, often # or //."}]}, {"type": "key_term", "term": "Script safety", "definition": "Review unsigned or unknown scripts before running them. A malicious script is malware.", "example": "A \"cleanup script\" from a forum turns out to add a scheduled task that downloads a remote payload."}, {"type": "scenario", "prompt": "A technician needs a script to run natively on Windows to bulk-create user accounts. Which extension fits best?", "choices": [{"id": "a", "text": ".sh"}, {"id": "b", "text": ".ps1"}, {"id": "c", "text": ".py"}, {"id": "d", "text": ".js"}], "answer": "b", "why": "PowerShell is the native, modern Windows choice."}, {"type": "scenario", "prompt": "Which construct repeats an action for every file in a folder?", "choices": [{"id": "a", "text": "Variable"}, {"id": "b", "text": "Loop"}, {"id": "c", "text": "Comment"}, {"id": "d", "text": "Conditional"}], "answer": "b", "why": "A loop."}, {"type": "callout", "variant": "tip", "text": ".ps1 and .bat for Windows, .sh for Linux and macOS, .py and .js anywhere. Review scripts before running."}]'::jsonb where id = '5d5016b1-9016-47d5-8475-2ff3cc8f2c10';

-- Remote Access Technologies
update lessons set content_blocks = '[{"text": "Remote Access Technologies", "type": "title", "overview": "The tools technicians use to remotely access and support a system, and the security considerations specific to remote access.", "examContext": "Why this matters: remote support is now a routine part of IT work, and the exam expects familiarity with the tools and their security tradeoffs."}, {"type": "compare", "heading": "Remote access tools", "columns": ["Type", "Notes"], "rows": [{"label": "RDP", "values": ["Graphical, Windows", "Port 3389; Pro or higher to host"]}, {"label": "VNC", "values": ["Graphical, cross-platform", "Windows, macOS, Linux"]}, {"label": "SSH", "values": ["Encrypted command line", "Port 22; Linux and network devices"]}, {"label": "VPN", "values": ["Encrypted tunnel", "Often used before other tools"]}, {"label": "Third-party support tools", "values": ["Screen share, file transfer", "Often with session recording"]}]}, {"type": "key_term", "term": "RMM", "definition": "Remote monitoring and management: watch disk, patches and services across many endpoints and act on the whole fleet.", "example": "An MSP''s RMM pushes a patch to 400 client PCs overnight and flags three with full disks."}, {"type": "term_set", "heading": "Security precautions", "terms": [{"term": "User consent", "short": "Ask before starting a session."}, {"term": "Strong authentication", "short": "MFA where possible."}, {"term": "Logging", "short": "Audit every session."}, {"term": "Never expose RDP directly", "short": "Put it behind a VPN."}]}, {"type": "scenario", "prompt": "A small business opened port 3389 on its firewall so staff can RDP in from home. What''s the fix?", "choices": [{"id": "a", "text": "Change the port number"}, {"id": "b", "text": "Require a VPN and stop exposing RDP to the internet"}, {"id": "c", "text": "Use Telnet instead"}, {"id": "d", "text": "Disable passwords"}], "answer": "b", "why": "Internet-exposed RDP is a common ransomware entry point."}, {"type": "scenario", "prompt": "A help desk needs graphical remote access to Linux and macOS machines. Which fits?", "choices": [{"id": "a", "text": "RDP"}, {"id": "b", "text": "VNC"}, {"id": "c", "text": "SSH"}, {"id": "d", "text": "RMM only"}], "answer": "b", "why": "VNC is graphical and cross-platform."}, {"type": "callout", "variant": "tip", "text": "Never expose RDP to the internet; tunnel it through a VPN. Always get consent first."}]'::jsonb where id = '96aada23-e9ae-486e-9904-d283f47b5b56';

-- Artificial Intelligence Concepts for IT Support
update lessons set content_blocks = '[{"text": "Artificial Intelligence Concepts for IT Support", "type": "title", "overview": "Basic AI concepts relevant to IT support work, this is a brand-new standalone objective (4.10) on 220-1202 that did not exist on the retired 220-1102 exam.", "examContext": "Why this matters: as one of the newest additions to A+ Core 2, this topic is likely to appear as straightforward definitional/scenario questions rather than deep technical detail."}, {"type": "paragraph", "text": "Generative AI tools are now common at work. Technicians don''t build them, but they advise users and enforce policy on safe use. This objective is new on 220-1202."}, {"type": "compare", "heading": "Key AI concepts", "columns": ["What it means", "Why it matters"], "rows": [{"label": "Hallucination", "values": ["Confident but false output", "Verify important claims"]}, {"label": "Data privacy", "values": ["Input may be stored or used for training", "Never paste sensitive data into unapproved tools"]}, {"label": "AI usage policy", "values": ["Which tools, what data, what review", "Follow it like any acceptable use policy"]}, {"label": "Bias", "values": ["Output can reflect training data bias", "Human review for anything customer facing"]}]}, {"type": "key_term", "term": "Hallucination", "definition": "Plausible, confident output that''s wrong or invented, such as a command that doesn''t exist.", "example": "A chatbot suggests a PowerShell parameter that doesn''t exist; running the script fails, or worse, does something unexpected."}, {"type": "scenario", "prompt": "A user pastes a spreadsheet of customer names and card numbers into a free public chatbot to summarize it. What''s the main concern?", "choices": [{"id": "a", "text": "Hallucination"}, {"id": "b", "text": "Data privacy and leakage"}, {"id": "c", "text": "Bias"}, {"id": "d", "text": "Slow performance"}], "answer": "b", "why": "Sensitive data has left the company''s control."}, {"type": "scenario", "prompt": "An AI tool writes a cleanup script for a technician. What should happen before running it?", "choices": [{"id": "a", "text": "Run it immediately"}, {"id": "b", "text": "Review it, since AI code can contain hallucinated or unsafe commands"}, {"id": "c", "text": "Email it to users"}, {"id": "d", "text": "Sign it without reading"}], "answer": "b", "why": "AI output needs human verification."}, {"type": "callout", "variant": "tip", "text": "Never put sensitive data into an unapproved AI tool. Always verify AI output before acting on it."}]'::jsonb where id = '8571e7dc-6a90-4422-a242-487827833f66';

-- Domain 4 Recap: Operational Procedures
update lessons set content_blocks = '[{"text": "Domain 4 Recap: Operational Procedures", "type": "title", "overview": "The highest-yield facts from all 8 Operational Procedures lessons, gathered in one place before the domain checkpoint.", "examContext": "Why this matters: this recap is ungraded, read it as a final consolidation pass before you attempt the 24-question checkpoint, and before the full Core 2 practice exams."}, {"type": "term_set", "heading": "Process and backup", "terms": [{"term": "Change management", "short": "Request, risk, rollback, approval, notify, implement."}, {"term": "Knowledge base", "short": "Faster repeat fixes."}, {"term": "Full / incremental / differential", "short": "Fastest restore / fastest backup / middle."}, {"term": "3-2-1", "short": "Three copies, two media, one off-site."}]}, {"type": "term_set", "heading": "Safety, policy and people", "terms": [{"term": "Class C", "short": "Electrical fires."}, {"term": "SDS", "short": "Hazardous material handling."}, {"term": "Prohibited content", "short": "Report, preserve, chain of custody."}, {"term": "PII / PHI / PCI", "short": "Identity / health / payment card."}, {"term": "Upset user", "short": "Stay calm, listen, focus on next steps."}]}, {"type": "term_set", "heading": "Scripts, remote access and AI", "terms": [{"term": ".ps1 / .sh / .py", "short": "Windows / Linux and macOS / cross-platform."}, {"term": "RDP", "short": "Behind a VPN, never exposed."}, {"term": "VNC / SSH / RMM", "short": "Cross-platform GUI / encrypted CLI / fleet management."}, {"term": "AI", "short": "Verify output; no sensitive data in unapproved tools."}]}, {"type": "scenario", "prompt": "Which backup needs the last full plus every backup since to restore?", "choices": [{"id": "a", "text": "Full"}, {"id": "b", "text": "Incremental"}, {"id": "c", "text": "Differential"}, {"id": "d", "text": "Synthetic full"}], "answer": "b", "why": "Incremental."}, {"type": "scenario", "prompt": "Which extinguisher for a burning monitor?", "choices": [{"id": "a", "text": "Water"}, {"id": "b", "text": "Class C"}, {"id": "c", "text": "Class A"}, {"id": "d", "text": "Foam"}], "answer": "b", "why": "Electrical fire."}, {"type": "scenario", "prompt": "A technician finds illegal content. First step?", "choices": [{"id": "a", "text": "Delete it"}, {"id": "b", "text": "Report through proper channels"}, {"id": "c", "text": "Investigate"}, {"id": "d", "text": "Forward to a colleague"}], "answer": "b", "why": "Report and preserve."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain, then the full Core 2 practice exams."}]'::jsonb where id = 'f004a94e-5d76-4a4d-8fb1-af3fca7ae3f7';
